window.IP_TERMS = [{"id": "0001", "f": "S", "sub": "企業と組織", "term": "経営理念", "desc": "企業が何のために存在し、社会にどんな価値を提供するかを示した基本的な考え方。"}, {"id": "0002", "f": "S", "sub": "企業と組織", "term": "ビジョン", "desc": "企業が将来ありたい姿を示したもの。経営理念をもとに、目指す方向を具体的に描く。"}, {"id": "0003", "f": "S", "sub": "企業と組織", "term": "株式会社", "desc": "株式を発行して出資者（株主）からお金を集め、事業を行う会社。株主は出資した額までしか責任を負わない。"}, {"id": "0004", "f": "S", "sub": "企業と組織", "term": "株主総会", "desc": "株式会社の最高意思決定機関。取締役の選任や決算の承認など、重要なことを株主が決める。"}, {"id": "0005", "f": "S", "sub": "企業と組織", "term": "取締役会", "desc": "取締役で構成され、会社の業務執行について意思決定を行う機関。"}, {"id": "0006", "f": "S", "sub": "企業と組織", "term": "CEO", "desc": "最高経営責任者のこと。会社の経営全体に責任を持つ。", "abbr": "Chief Executive Officer"}, {"id": "0007", "f": "S", "sub": "企業と組織", "term": "CIO", "desc": "最高情報責任者のこと。情報システムやIT戦略に責任を持つ役員。", "abbr": "Chief Information Officer"}, {"id": "0008", "f": "S", "sub": "企業と組織", "term": "ステークホルダ", "desc": "株主・顧客・従業員・取引先・地域社会など、企業の活動に利害関係を持つ人や組織。"}, {"id": "0009", "f": "S", "sub": "企業と組織", "term": "CSR", "desc": "企業の社会的責任のこと。利益を追うだけでなく、環境・地域社会・従業員などに配慮して行動する責任。", "abbr": "Corporate Social Responsibility"}, {"id": "0010", "f": "S", "sub": "企業と組織", "term": "SDGs", "desc": "国連で採択された、2030年までに達成を目指す17の「持続可能な開発目標」。", "abbr": "Sustainable Development Goals"}, {"id": "0011", "f": "S", "sub": "企業と組織", "term": "ESG投資", "desc": "環境（Environment）・社会（Social）・企業統治（Governance）への取組みを重視して、投資先を選ぶこと。"}, {"id": "0012", "f": "S", "sub": "企業と組織", "term": "グリーンIT", "desc": "IT機器の省エネルギー化や、ITを使った環境への負荷の低減に取り組むこと。"}, {"id": "0013", "f": "S", "sub": "企業と組織", "term": "コーポレートガバナンス", "desc": "経営者の行動を監視し、企業の経営が健全・適正に行われるようにする仕組み。企業統治とも呼ぶ。"}, {"id": "0014", "f": "S", "sub": "企業と組織", "term": "ディスクロージャ", "desc": "企業が投資家などに向けて、経営の状態や財務の情報を公開すること。"}, {"id": "0015", "f": "S", "sub": "企業と組織", "term": "IR", "desc": "投資家向け広報のこと。株主や投資家に向けて、経営や財務の情報を発信する活動。", "abbr": "Investor Relations"}, {"id": "0016", "f": "S", "sub": "企業と組織", "term": "BCP", "desc": "事業継続計画のこと。災害や事故が起きても、重要な業務を続けたり早く再開したりするための計画。", "abbr": "Business Continuity Plan"}, {"id": "0017", "f": "S", "sub": "企業と組織", "term": "BCM", "desc": "事業継続マネジメントのこと。BCPを作るだけでなく、訓練や見直しを続けて、事業を続ける力を高める活動。", "abbr": "Business Continuity Management"}, {"id": "0018", "f": "S", "sub": "企業と組織", "term": "職能別組織", "desc": "営業・製造・経理など、仕事の機能ごとに部門を分けた組織。"}, {"id": "0019", "f": "S", "sub": "企業と組織", "term": "事業部制組織", "desc": "製品や地域ごとに事業部を作り、各事業部が利益に責任を持って独立して運営する組織。"}, {"id": "0020", "f": "S", "sub": "企業と組織", "term": "マトリックス組織", "desc": "職能別と事業別（プロジェクト別）など、2つの指揮命令系統を組み合わせた組織。1人が2人の上司を持つことになる。"}, {"id": "0021", "f": "S", "sub": "企業と組織", "term": "プロジェクト組織", "desc": "特定の目的のために各部門から人を集め、目的を達成したら解散する一時的な組織。"}, {"id": "0022", "f": "S", "sub": "企業と組織", "term": "カンパニー制", "desc": "事業部をさらに独立した1つの会社のように扱い、大きな権限と責任を持たせる組織の形。"}, {"id": "0023", "f": "S", "sub": "企業と組織", "term": "持株会社", "desc": "他の会社の株式を持ち、その会社を支配・管理することを主な目的とする会社。"}, {"id": "0024", "f": "S", "sub": "企業と組織", "term": "OJT", "desc": "職場で実際の仕事をしながら、上司や先輩が仕事に必要な知識や技能を教える教育方法。", "abbr": "On the Job Training"}, {"id": "0025", "f": "S", "sub": "企業と組織", "term": "Off-JT", "desc": "職場を離れて、研修やセミナーなどで行う教育。", "abbr": "Off the Job Training"}, {"id": "0026", "f": "S", "sub": "企業と組織", "term": "eラーニング", "desc": "パソコンやスマートフォンとネットワークを使って学ぶ学習方法。"}, {"id": "0027", "f": "S", "sub": "企業と組織", "term": "アダプティブラーニング", "desc": "学ぶ人の理解度や進み具合に合わせて、内容や順番を変える学習方法。"}, {"id": "0028", "f": "S", "sub": "企業と組織", "term": "HRテック", "desc": "AIやクラウドなどのITを使って、採用・育成・評価などの人事の仕事を効率化すること。"}, {"id": "0029", "f": "S", "sub": "企業と組織", "term": "ダイバーシティ", "desc": "性別・年齢・国籍などが異なる多様な人材を受け入れ、活かすこと。"}, {"id": "0030", "f": "S", "sub": "企業と組織", "term": "ワークライフバランス", "desc": "仕事と、家庭や趣味などの生活との調和をとること。"}, {"id": "0031", "f": "S", "sub": "企業と組織", "term": "テレワーク", "desc": "ITを使って、会社以外の場所（自宅など）で働くこと。"}, {"id": "0032", "f": "S", "sub": "業務分析", "term": "PDCAサイクル", "desc": "計画（Plan）・実行（Do）・評価（Check）・改善（Act）を繰り返して、業務を継続的に良くしていく考え方。"}, {"id": "0033", "f": "S", "sub": "業務分析", "term": "パレート図", "desc": "項目を値の大きい順に棒グラフで並べ、その累積の割合を折れ線グラフで重ねた図。重要な項目を見つけるのに使う。"}, {"id": "0034", "f": "S", "sub": "業務分析", "term": "ABC分析", "desc": "パレート図をもとに、項目を重要度の高い順にA・B・Cのグループに分けて、管理の重点を決める手法。"}, {"id": "0035", "f": "S", "sub": "業務分析", "term": "特性要因図", "desc": "結果（特性）と、それに影響する原因（要因）の関係を、魚の骨のような形で整理した図。"}, {"id": "0036", "f": "S", "sub": "業務分析", "term": "散布図", "desc": "2つの項目のデータを縦軸と横軸に取って点を打ち、2つの項目の関係（相関）を見る図。"}, {"id": "0037", "f": "S", "sub": "業務分析", "term": "管理図", "desc": "データを時間の順に折れ線で表し、上と下の管理限界線と比べて、工程が安定しているかを見る図。"}, {"id": "0038", "f": "S", "sub": "業務分析", "term": "ヒストグラム", "desc": "データをいくつかの区間に分け、各区間に入るデータの数を棒グラフで表した図。データのばらつきを見るのに使う。"}, {"id": "0039", "f": "S", "sub": "業務分析", "term": "レーダーチャート", "desc": "複数の項目の値を、中心から放射状に伸びる軸の上に取って線で結んだグラフ。全体のバランスを見るのに使う。"}, {"id": "0040", "f": "S", "sub": "業務分析", "term": "チェックシート", "desc": "確認する項目や記録の欄をあらかじめ用意し、チェックを付けて集計しやすくした表。"}, {"id": "0041", "f": "S", "sub": "業務分析", "term": "QC七つ道具", "desc": "品質管理でよく使う7つの手法。パレート図・特性要因図・ヒストグラム・散布図・管理図・チェックシート・グラフ（層別を入れることもある）。"}, {"id": "0042", "f": "S", "sub": "業務分析", "term": "ブレーンストーミング", "desc": "複数の人が自由にアイデアを出し合う方法。他人の意見を批判しない、質より量を重視するなどのルールがある。"}, {"id": "0043", "f": "S", "sub": "業務分析", "term": "親和図法", "desc": "集めた意見や情報を、内容が似ているものどうしでグループにまとめて整理する手法。"}, {"id": "0044", "f": "S", "sub": "業務分析", "term": "デルファイ法", "desc": "複数の専門家にアンケートを行い、その結果を見せて再び意見を聞くことを繰り返して、予測をまとめる手法。"}, {"id": "0045", "f": "S", "sub": "業務分析", "term": "相関係数", "desc": "2つのデータの関係の強さを、−1から1の数で表したもの。1に近いほど正の相関が、−1に近いほど負の相関が強い。"}, {"id": "0046", "f": "S", "sub": "業務分析", "term": "回帰分析", "desc": "あるデータ（結果）が、別のデータ（原因）からどのように決まるかを式で表して分析する手法。"}, {"id": "0047", "f": "S", "sub": "業務分析", "term": "デシジョンツリー", "desc": "選択肢とその結果を木のように枝分かれさせて描き、どれを選ぶと良いかを判断するための図。"}, {"id": "0048", "f": "S", "sub": "業務分析", "term": "定量発注方式", "desc": "在庫が決められた量（発注点）まで減ったら、決まった量を発注する在庫管理の方法。"}, {"id": "0049", "f": "S", "sub": "業務分析", "term": "定期発注方式", "desc": "決まった間隔（例: 毎月）で、そのときに必要な量を計算して発注する在庫管理の方法。"}, {"id": "0050", "f": "S", "sub": "業務分析", "term": "ジャストインタイム", "desc": "必要なものを、必要なときに、必要な量だけ作ったり届けたりして、在庫を減らす生産方式。"}, {"id": "0051", "f": "S", "sub": "会計・財務", "term": "財務諸表", "desc": "会社の経営成績や財政状態を示す書類。損益計算書・貸借対照表・キャッシュフロー計算書など。"}, {"id": "0052", "f": "S", "sub": "会計・財務", "term": "損益計算書", "desc": "一定の期間に、どれだけの収益と費用があり、どれだけ利益が出たかを示す財務諸表。P/Lとも呼ぶ。"}, {"id": "0053", "f": "S", "sub": "会計・財務", "term": "貸借対照表", "desc": "ある時点で、会社がどんな資産を持ち、どれだけの負債と純資産があるかを示す財務諸表。B/Sとも呼ぶ。"}, {"id": "0054", "f": "S", "sub": "会計・財務", "term": "キャッシュフロー計算書", "desc": "一定の期間に、お金（現金など）がどのように入ってきて、出ていったかを示す財務諸表。"}, {"id": "0055", "f": "S", "sub": "会計・財務", "term": "売上原価", "desc": "売れた商品を仕入れたり作ったりするのにかかった費用。"}, {"id": "0056", "f": "S", "sub": "会計・財務", "term": "売上総利益（粗利）", "desc": "売上高から売上原価を引いた利益。"}, {"id": "0057", "f": "S", "sub": "会計・財務", "term": "販売費及び一般管理費", "desc": "商品を売るための費用や、会社全体を管理するための費用。広告費・人件費・家賃など。"}, {"id": "0058", "f": "S", "sub": "会計・財務", "term": "営業利益", "desc": "売上総利益から、販売費及び一般管理費を引いた利益。本業でのもうけを表す。"}, {"id": "0059", "f": "S", "sub": "会計・財務", "term": "経常利益", "desc": "営業利益に、受取利息などの本業以外の収益を足し、支払利息などの本業以外の費用を引いた利益。"}, {"id": "0060", "f": "S", "sub": "会計・財務", "term": "当期純利益", "desc": "経常利益に特別な利益や損失（土地の売却など）を加減し、法人税などを引いた、最終的な利益。"}, {"id": "0061", "f": "S", "sub": "会計・財務", "term": "資産", "desc": "会社が持っている財産。現金・売掛金・商品・建物など。"}, {"id": "0062", "f": "S", "sub": "会計・財務", "term": "負債", "desc": "会社が将来、返したり払ったりしなければならないもの。借入金・買掛金など。"}, {"id": "0063", "f": "S", "sub": "会計・財務", "term": "純資産", "desc": "資産から負債を引いた残り。株主が出したお金（資本金）や、これまでの利益の積み上げなど。"}, {"id": "0064", "f": "S", "sub": "会計・財務", "term": "流動資産", "desc": "現金や売掛金など、おおむね1年以内に現金に変わる資産。"}, {"id": "0065", "f": "S", "sub": "会計・財務", "term": "固定資産", "desc": "土地・建物・機械など、1年を超えて長く使う資産。"}, {"id": "0066", "f": "S", "sub": "会計・財務", "term": "売掛金", "desc": "商品を売ったが、まだ受け取っていない代金。"}, {"id": "0067", "f": "S", "sub": "会計・財務", "term": "買掛金", "desc": "商品を仕入れたが、まだ支払っていない代金。"}, {"id": "0068", "f": "S", "sub": "会計・財務", "term": "損益分岐点", "desc": "売上高と費用が等しくなり、利益も損失も出ない点。売上がこれより多いと利益が出る。"}, {"id": "0069", "f": "S", "sub": "会計・財務", "term": "変動費", "desc": "材料費など、売上や生産量に応じて増えたり減ったりする費用。"}, {"id": "0070", "f": "S", "sub": "会計・財務", "term": "固定費", "desc": "家賃や正社員の給料など、売上や生産量に関係なくかかる費用。"}, {"id": "0071", "f": "S", "sub": "会計・財務", "term": "変動費率", "desc": "売上高に対する変動費の割合。損益分岐点の売上高は「固定費 ÷（1 − 変動費率）」で求める。"}, {"id": "0072", "f": "S", "sub": "会計・財務", "term": "減価償却", "desc": "建物や機械など長く使う資産の購入費用を、使う期間（耐用年数）に分けて少しずつ費用にすること。"}, {"id": "0073", "f": "S", "sub": "会計・財務", "term": "ROE", "desc": "自己資本利益率のこと。株主が出したお金（自己資本）に対して、どれだけ利益を上げたかを示す指標。", "abbr": "Return On Equity"}, {"id": "0074", "f": "S", "sub": "会計・財務", "term": "ROA", "desc": "総資産利益率のこと。会社が持つすべての資産を使って、どれだけ利益を上げたかを示す指標。", "abbr": "Return On Assets"}, {"id": "0075", "f": "S", "sub": "会計・財務", "term": "流動比率", "desc": "流動負債に対する流動資産の割合。短い期間で支払う力（安全性）を示し、高いほど安全とされる。"}, {"id": "0076", "f": "S", "sub": "会計・財務", "term": "自己資本比率", "desc": "総資産のうち、返す必要のない自己資本が占める割合。高いほど経営が安定しているとされる。"}, {"id": "0077", "f": "S", "sub": "会計・財務", "term": "先入先出法", "desc": "先に仕入れたものから先に払い出したとみなして、在庫の金額を計算する方法。"}, {"id": "0078", "f": "S", "sub": "会計・財務", "term": "移動平均法", "desc": "仕入れのたびに、それまでの在庫と合わせた平均の単価を計算し直して、在庫の金額を求める方法。"}, {"id": "0079", "f": "S", "sub": "知的財産権", "term": "著作権", "desc": "小説・音楽・絵・プログラムなどの著作物を作った人に与えられる権利。作った時点で自動的に生まれ、登録はいらない。"}, {"id": "0080", "f": "S", "sub": "知的財産権", "term": "著作者人格権", "desc": "著作者の名誉や気持ちを守る権利。公表権・氏名表示権・同一性保持権がある。他人に譲ることはできない。"}, {"id": "0081", "f": "S", "sub": "知的財産権", "term": "産業財産権", "desc": "特許権・実用新案権・意匠権・商標権の4つ。特許庁に出願し、登録されると権利が生まれる。"}, {"id": "0082", "f": "S", "sub": "知的財産権", "term": "特許権", "desc": "新しく高度な発明を、一定の期間、独占して使える権利。"}, {"id": "0083", "f": "S", "sub": "知的財産権", "term": "実用新案権", "desc": "物の形や構造などの考案（小発明）を保護する権利。"}, {"id": "0084", "f": "S", "sub": "知的財産権", "term": "意匠権", "desc": "製品の形・模様・色などのデザインを保護する権利。"}, {"id": "0085", "f": "S", "sub": "知的財産権", "term": "商標権", "desc": "商品やサービスに付ける名前やマーク（商標）を保護する権利。"}, {"id": "0086", "f": "S", "sub": "知的財産権", "term": "ビジネスモデル特許", "desc": "ITを使った新しいビジネスの方法について認められた特許。"}, {"id": "0087", "f": "S", "sub": "知的財産権", "term": "営業秘密", "desc": "秘密として管理され、事業に役立ち、世間に知られていない情報。顧客名簿や製造のノウハウなど。不正競争防止法で守られる。"}, {"id": "0088", "f": "S", "sub": "知的財産権", "term": "不正競争防止法", "desc": "営業秘密を盗むことや、有名な商品の表示をまねることなど、事業者どうしの不正な競争を防ぐための法律。"}, {"id": "0089", "f": "S", "sub": "知的財産権", "term": "使用許諾契約", "desc": "ソフトウェアなどの権利を持つ者が、他人がそれを使うことを認める契約。ライセンス契約とも呼ぶ。"}, {"id": "0090", "f": "S", "sub": "知的財産権", "term": "シュリンクラップ契約", "desc": "ソフトウェアの包装を開けた時点で、使用許諾の条件に同意したとみなす契約の形。"}, {"id": "0091", "f": "S", "sub": "知的財産権", "term": "ボリュームライセンス", "desc": "企業などがソフトウェアをまとめて導入するときに、複数の台数分の利用をまとめて許可する契約。"}, {"id": "0092", "f": "S", "sub": "知的財産権", "term": "サブスクリプション", "desc": "一定の期間ごとに料金を払う方式。払っている間は、ソフトウェアやサービスを使える。"}, {"id": "0093", "f": "S", "sub": "知的財産権", "term": "クロスライセンス", "desc": "2つの企業が、互いに持っている特許などの権利を使うことを認め合う契約。"}, {"id": "0094", "f": "S", "sub": "知的財産権", "term": "クリエイティブ・コモンズ", "desc": "作品を作った人が「この条件を守れば自由に使ってよい」という意思を示すための仕組み。CCライセンスとも呼ぶ。"}, {"id": "0095", "f": "S", "sub": "セキュリティの法律", "term": "不正アクセス禁止法", "desc": "他人のIDやパスワードを無断で使ってコンピュータに入ることや、それを助けることを禁止する法律。"}, {"id": "0096", "f": "S", "sub": "セキュリティの法律", "term": "サイバーセキュリティ基本法", "desc": "国や地方公共団体などの、サイバーセキュリティに関する責任や施策の基本を定めた法律。"}, {"id": "0097", "f": "S", "sub": "セキュリティの法律", "term": "不正指令電磁的記録に関する罪", "desc": "正当な理由なく、コンピュータウイルスを作ったり、人に渡したり、取得・保管したりすることを罰する刑法の罪。ウイルス作成罪とも呼ぶ。"}, {"id": "0098", "f": "S", "sub": "セキュリティの法律", "term": "個人情報保護法", "desc": "個人情報を扱う事業者が守るべきルールを定めた法律。利用目的をはっきりさせることや、本人の同意のない第三者への提供の制限などがある。"}, {"id": "0099", "f": "S", "sub": "セキュリティの法律", "term": "個人情報", "desc": "生きている個人に関する情報で、氏名や生年月日などによって特定の個人を識別できるもの。"}, {"id": "0100", "f": "S", "sub": "セキュリティの法律", "term": "要配慮個人情報", "desc": "人種・信条・病歴・犯罪歴など、扱いを誤ると差別や偏見につながるおそれがあり、特に配慮が必要な個人情報。"}, {"id": "0101", "f": "S", "sub": "セキュリティの法律", "term": "匿名加工情報", "desc": "特定の個人を識別できないように加工し、元の個人情報に戻せないようにした情報。"}, {"id": "0102", "f": "S", "sub": "セキュリティの法律", "term": "仮名加工情報", "desc": "他の情報と照らし合わせない限り、特定の個人を識別できないように加工した情報。社内での分析などに使う。"}, {"id": "0103", "f": "S", "sub": "セキュリティの法律", "term": "マイナンバー法", "desc": "マイナンバー（個人番号）の利用や管理について定めた法律。番号を使える場面は限られている。"}, {"id": "0104", "f": "S", "sub": "セキュリティの法律", "term": "特定電子メール法", "desc": "広告などの迷惑メールを規制する法律。原則として、あらかじめ同意した人にしか広告メールを送れない。"}, {"id": "0105", "f": "S", "sub": "セキュリティの法律", "term": "オプトイン", "desc": "メールの送信や情報の利用などを、本人があらかじめ同意した場合にだけ行う方式。"}, {"id": "0106", "f": "S", "sub": "セキュリティの法律", "term": "オプトアウト", "desc": "本人が拒否するまではメールの送信などを行い、拒否されたら止める方式。"}, {"id": "0107", "f": "S", "sub": "セキュリティの法律", "term": "情報流通プラットフォーム対処法（プロバイダ責任制限法）", "desc": "SNSなどで権利を侵害する書き込みがあったときの事業者の責任や、発信者の情報の開示、大規模なプラットフォーム事業者が行うべき対応を定めた法律。2025年4月に、プロバイダ責任制限法が改正されて今の名前になった。"}, {"id": "0108", "f": "S", "sub": "セキュリティの法律", "term": "電子署名法", "desc": "一定の条件を満たした電子署名が、手書きの署名や押印と同じように扱われることを定めた法律。"}, {"id": "0109", "f": "S", "sub": "セキュリティの法律", "term": "GDPR", "desc": "EU（欧州連合）の一般データ保護規則。EUの中の個人データの扱いを定めたもので、EUの外の企業にも適用されることがある。", "abbr": "General Data Protection Regulation"}, {"id": "0110", "f": "S", "sub": "セキュリティの法律", "term": "サイバーセキュリティ経営ガイドライン", "desc": "経営者がリーダーシップをとってサイバーセキュリティ対策を進めるための指針。経済産業省とIPAがまとめた。"}, {"id": "0111", "f": "S", "sub": "労働・取引の法律", "term": "労働基準法", "desc": "労働時間・休日・賃金など、働く条件の最低の基準を定めた法律。"}, {"id": "0112", "f": "S", "sub": "労働・取引の法律", "term": "36協定", "desc": "法定労働時間を超えて残業や休日出勤をさせる場合に、会社と労働者の代表が結び、労働基準監督署に届け出る協定。"}, {"id": "0113", "f": "S", "sub": "労働・取引の法律", "term": "フレックスタイム制", "desc": "一定の期間の総労働時間を決めたうえで、毎日の始業と終業の時刻を、労働者が自分で決められる制度。"}, {"id": "0114", "f": "S", "sub": "労働・取引の法律", "term": "裁量労働制", "desc": "実際に働いた時間に関係なく、あらかじめ決めた時間を働いたものとみなす制度。研究開発など、働き方を本人に任せる仕事で使う。"}, {"id": "0115", "f": "S", "sub": "労働・取引の法律", "term": "労働者派遣法", "desc": "派遣元の会社が雇っている労働者を、派遣先の会社で働かせる「労働者派遣」のルールを定めた法律。"}, {"id": "0116", "f": "S", "sub": "労働・取引の法律", "term": "労働者派遣", "desc": "派遣元と雇用契約を結んだ労働者が、派遣先の指揮命令を受けて働く形。"}, {"id": "0117", "f": "S", "sub": "労働・取引の法律", "term": "請負契約", "desc": "仕事の完成を約束し、その結果に対して報酬を受け取る契約。作業の指示は、仕事を請け負った側が行う。"}, {"id": "0118", "f": "S", "sub": "労働・取引の法律", "term": "準委任契約", "desc": "仕事の完成ではなく、決められた事務を行うこと（作業そのもの）を約束する契約。"}, {"id": "0119", "f": "S", "sub": "労働・取引の法律", "term": "偽装請負", "desc": "契約は請負なのに、実際には発注した側が、請け負った側の労働者に直接作業の指示をしている状態。法律違反になる。"}, {"id": "0120", "f": "S", "sub": "労働・取引の法律", "term": "取適法（中小受託取引適正化法、下請法）", "desc": "仕事を発注する事業者が、中小の受託事業者への代金の支払いを遅らせたり、一方的に減らしたりすることなどを禁止する法律。2026年1月に下請法が改正されて今の名前になった。"}, {"id": "0121", "f": "S", "sub": "労働・取引の法律", "term": "製造物責任法（PL法）", "desc": "製品の欠陥によって人がけがをしたり物が壊れたりしたときに、製造業者などが損害を賠償する責任を負うことを定めた法律。"}, {"id": "0122", "f": "S", "sub": "労働・取引の法律", "term": "公益通報者保護法", "desc": "会社の法令違反などを通報（公益通報）した労働者が、解雇などの不利益を受けないように守る法律。"}, {"id": "0123", "f": "S", "sub": "労働・取引の法律", "term": "特定商取引法", "desc": "訪問販売や通信販売など、トラブルが起きやすい取引について、事業者が守るルールやクーリング・オフなどを定めた法律。"}, {"id": "0124", "f": "S", "sub": "労働・取引の法律", "term": "景品表示法", "desc": "商品やサービスを実際より良く見せる表示や、行き過ぎた景品を付けることを規制する法律。"}, {"id": "0125", "f": "S", "sub": "労働・取引の法律", "term": "ステルスマーケティング", "desc": "広告であることを隠して、商品やサービスを宣伝すること。日本では景品表示法の規制の対象になっている。"}, {"id": "0126", "f": "S", "sub": "労働・取引の法律", "term": "資金決済法", "desc": "電子マネーなどの前払式の支払手段、送金のサービス、暗号資産などについて定めた法律。"}, {"id": "0127", "f": "S", "sub": "労働・取引の法律", "term": "暗号資産", "desc": "インターネット上でやり取りされる、財産としての価値を持つデータ。ビットコインなど。以前は仮想通貨と呼ばれていた。"}, {"id": "0128", "f": "S", "sub": "労働・取引の法律", "term": "金融商品取引法", "desc": "株式などの金融商品の取引について、投資家を守るためのルールを定めた法律。上場企業の内部統制の報告も、この法律に基づく。"}, {"id": "0129", "f": "S", "sub": "労働・取引の法律", "term": "NDA", "desc": "秘密保持契約のこと。取引の中で知った相手の秘密の情報を、外に漏らさないことを約束する契約。", "abbr": "Non-Disclosure Agreement"}, {"id": "0130", "f": "S", "sub": "標準化・倫理", "term": "コンプライアンス", "desc": "法令遵守のこと。法律だけでなく、社内の規則や社会の規範も守って行動すること。"}, {"id": "0131", "f": "S", "sub": "標準化・倫理", "term": "情報倫理", "desc": "情報を扱ったり、インターネットを使ったりするときに守るべき道徳や考え方。"}, {"id": "0132", "f": "S", "sub": "標準化・倫理", "term": "標準化", "desc": "製品の形や規格、手順などを統一すること。互換性が高まり、費用を下げられる。"}, {"id": "0133", "f": "S", "sub": "標準化・倫理", "term": "デファクトスタンダード", "desc": "公的な機関が決めたものではないが、市場で広く使われた結果、事実上の標準になった規格。"}, {"id": "0134", "f": "S", "sub": "標準化・倫理", "term": "デジュレスタンダード", "desc": "ISOやJISなど、公的な標準化機関が定めた標準。"}, {"id": "0135", "f": "S", "sub": "標準化・倫理", "term": "ISO", "desc": "国際標準化機構のこと。工業や技術などの国際規格を作る組織。", "abbr": "International Organization for Standardization"}, {"id": "0136", "f": "S", "sub": "標準化・倫理", "term": "JIS", "desc": "日本産業規格のこと。日本の産業製品やデータ、サービスなどに関する国の規格。", "abbr": "Japanese Industrial Standards"}, {"id": "0137", "f": "S", "sub": "標準化・倫理", "term": "IEEE", "desc": "米国に本部がある電気・電子工学の学会。無線LAN（IEEE 802.11）などの規格を作っている。", "abbr": "Institute of Electrical and Electronics Engineers"}, {"id": "0138", "f": "S", "sub": "標準化・倫理", "term": "W3C", "desc": "Webで使う技術（HTMLなど）の標準を作る国際的な団体。", "abbr": "World Wide Web Consortium"}, {"id": "0139", "f": "S", "sub": "標準化・倫理", "term": "ISO 9001", "desc": "品質マネジメントシステムの国際規格。"}, {"id": "0140", "f": "S", "sub": "標準化・倫理", "term": "ISO 14001", "desc": "環境マネジメントシステムの国際規格。"}, {"id": "0141", "f": "S", "sub": "標準化・倫理", "term": "ISO/IEC 27001", "desc": "情報セキュリティマネジメントシステム（ISMS）の国際規格。"}, {"id": "0142", "f": "S", "sub": "標準化・倫理", "term": "JANコード", "desc": "商品に付けるバーコードの規格。国・メーカー・商品などを表す数字を持ち、POSシステムで読み取る。"}, {"id": "0143", "f": "S", "sub": "標準化・倫理", "term": "QRコード", "desc": "縦と横の2つの方向に情報を持つ2次元コード。バーコードより多くの情報を記録でき、汚れにも比較的強い。"}, {"id": "0144", "f": "S", "sub": "経営戦略", "term": "SWOT分析", "desc": "自社の強み（Strengths）・弱み（Weaknesses）と、外部の機会（Opportunities）・脅威（Threats）を整理して、戦略を考える分析手法。"}, {"id": "0145", "f": "S", "sub": "経営戦略", "term": "3C分析", "desc": "顧客（Customer）・競合（Competitor）・自社（Company）の3つの視点から、事業の環境を分析する手法。"}, {"id": "0146", "f": "S", "sub": "経営戦略", "term": "PEST分析", "desc": "政治（Politics）・経済（Economy）・社会（Society）・技術（Technology）の4つの視点から、外部の大きな環境の変化を分析する手法。"}, {"id": "0147", "f": "S", "sub": "経営戦略", "term": "ファイブフォース分析", "desc": "業界の競争の強さを、既存の競合・新しく参入する企業・代替品・買い手・売り手の5つの力から分析する手法。"}, {"id": "0148", "f": "S", "sub": "経営戦略", "term": "PPM", "desc": "市場の成長率と市場の占有率の2つの軸で、事業を「花形・金のなる木・問題児・負け犬」に分け、経営資源の配分を考える手法。", "abbr": "Product Portfolio Management"}, {"id": "0149", "f": "S", "sub": "経営戦略", "term": "アンゾフの成長マトリクス", "desc": "製品（既存・新規）と市場（既存・新規）の組合せで、市場浸透・新製品開発・新市場開拓・多角化の4つの成長戦略に分ける考え方。"}, {"id": "0150", "f": "S", "sub": "経営戦略", "term": "コアコンピタンス", "desc": "他社にまねされにくい、自社の中核となる強みの技術や能力。"}, {"id": "0151", "f": "S", "sub": "経営戦略", "term": "コストリーダーシップ戦略", "desc": "他社より低いコストで作ったり売ったりすることで、競争で優位に立つ戦略。"}, {"id": "0152", "f": "S", "sub": "経営戦略", "term": "差別化戦略", "desc": "品質・機能・デザインなどで他社の製品との違いを打ち出し、競争で優位に立つ戦略。"}, {"id": "0153", "f": "S", "sub": "経営戦略", "term": "ニッチ戦略", "desc": "大企業が狙わない小さな市場（すき間）に絞り込み、その中で優位に立つ戦略。"}, {"id": "0154", "f": "S", "sub": "経営戦略", "term": "ブルーオーシャン戦略", "desc": "競争相手のいない新しい市場（ブルーオーシャン）を作り出して、事業を伸ばす戦略。"}, {"id": "0155", "f": "S", "sub": "経営戦略", "term": "競争地位別戦略", "desc": "市場での立場（リーダ・チャレンジャ・フォロワ・ニッチャ）によって、取るべき戦略が異なるという考え方。"}, {"id": "0156", "f": "S", "sub": "経営戦略", "term": "ベンチマーキング", "desc": "優れた他社のやり方と自社を比べ、良いところを取り入れて改善する手法。"}, {"id": "0157", "f": "S", "sub": "経営戦略", "term": "規模の経済", "desc": "生産量を増やすほど、製品1個あたりのコストが下がること。"}, {"id": "0158", "f": "S", "sub": "経営戦略", "term": "シナジー", "desc": "複数の事業や企業を組み合わせることで、別々に行うより大きな効果が生まれること。相乗効果。"}, {"id": "0159", "f": "S", "sub": "経営戦略", "term": "コモディティ化", "desc": "製品の機能や品質に差がなくなり、価格だけで選ばれるようになること。"}, {"id": "0160", "f": "S", "sub": "経営戦略", "term": "M&A", "desc": "企業の合併（Mergers）と買収（Acquisitions）のこと。他社の事業や技術を短い期間で手に入れられる。", "abbr": "Mergers and Acquisitions"}, {"id": "0161", "f": "S", "sub": "経営戦略", "term": "TOB", "desc": "株式公開買付けのこと。買う期間・価格・株数を公表して、市場の外で株主から株式を買い集める方法。", "abbr": "Take Over Bid"}, {"id": "0162", "f": "S", "sub": "経営戦略", "term": "MBO", "desc": "経営陣が自分の会社の株式を買い取り、経営権を手に入れること。マネジメントバイアウトとも呼ぶ。", "abbr": "Management Buyout"}, {"id": "0163", "f": "S", "sub": "経営戦略", "term": "アライアンス", "desc": "企業どうしが、技術や販売などで協力し合う提携のこと。"}, {"id": "0164", "f": "S", "sub": "経営戦略", "term": "ジョイントベンチャ", "desc": "複数の企業が共同で出資して、新しい会社を作ること。合弁会社。"}, {"id": "0165", "f": "S", "sub": "経営戦略", "term": "アウトソーシング", "desc": "自社の業務の一部を、外部の専門の会社に任せること。"}, {"id": "0166", "f": "S", "sub": "経営戦略", "term": "垂直統合", "desc": "原材料の調達から製造・販売まで、製品の流れの上流から下流までを自社のグループで行うこと。"}, {"id": "0167", "f": "S", "sub": "経営戦略", "term": "ファブレス", "desc": "自社では工場を持たず、製品の企画や設計などに集中し、製造は外部の会社に任せる経営の形。"}, {"id": "0168", "f": "S", "sub": "経営戦略", "term": "OEM", "desc": "相手先のブランドで製品を製造すること。他社のブランド名で売られる製品を作る。", "abbr": "Original Equipment Manufacturing"}, {"id": "0169", "f": "S", "sub": "経営戦略", "term": "フランチャイズチェーン", "desc": "本部が加盟店に商標や経営のノウハウを提供し、加盟店がその対価を払う形の事業。"}, {"id": "0170", "f": "S", "sub": "マーケティング", "term": "マーケティングミックス", "desc": "売り手が使える要素を組み合わせて、販売を進めること。製品・価格・流通・販売促進の4Pが代表的。"}, {"id": "0171", "f": "S", "sub": "マーケティング", "term": "4P", "desc": "売り手の視点から見たマーケティングの要素。製品（Product）・価格（Price）・流通（Place）・販売促進（Promotion）。"}, {"id": "0172", "f": "S", "sub": "マーケティング", "term": "4C", "desc": "買い手の視点から見たマーケティングの要素。顧客にとっての価値・顧客の負担・利便性・コミュニケーション。"}, {"id": "0173", "f": "S", "sub": "マーケティング", "term": "セグメンテーション", "desc": "年齢・地域・好みなどの基準で、市場をいくつかのグループに分けること。"}, {"id": "0174", "f": "S", "sub": "マーケティング", "term": "ターゲティング", "desc": "分けた市場（セグメント）の中から、狙う市場を決めること。"}, {"id": "0175", "f": "S", "sub": "マーケティング", "term": "ポジショニング", "desc": "狙った市場の中で、競合と比べた自社の製品の立ち位置を決めること。"}, {"id": "0176", "f": "S", "sub": "マーケティング", "term": "プロダクトライフサイクル", "desc": "製品が市場に出てから消えるまでを、導入期・成長期・成熟期・衰退期の4つに分けて考えるもの。"}, {"id": "0177", "f": "S", "sub": "マーケティング", "term": "プッシュ戦略", "desc": "販売店に働きかけたり、営業担当者が勧めたりして、商品を顧客に押し出すように売る戦略。"}, {"id": "0178", "f": "S", "sub": "マーケティング", "term": "プル戦略", "desc": "広告などで顧客の買いたい気持ちを高め、顧客のほうから商品を求めてもらう戦略。"}, {"id": "0179", "f": "S", "sub": "マーケティング", "term": "オピニオンリーダ", "desc": "周りの人の考えや買い物に、大きな影響を与える人。"}, {"id": "0180", "f": "S", "sub": "マーケティング", "term": "バイラルマーケティング", "desc": "口コミで情報が人から人へ広がることを利用して、商品やサービスを広める手法。"}, {"id": "0181", "f": "S", "sub": "マーケティング", "term": "アフィリエイト", "desc": "Webサイトなどに広告を載せ、そこから商品が売れたり申し込まれたりしたときに、サイトの運営者に報酬が支払われる仕組み。"}, {"id": "0182", "f": "S", "sub": "マーケティング", "term": "リスティング広告", "desc": "検索エンジンで検索された言葉に合わせて、検索結果の画面に表示される広告。検索連動型広告とも呼ぶ。"}, {"id": "0183", "f": "S", "sub": "マーケティング", "term": "SEO", "desc": "検索エンジン最適化のこと。検索結果で自分のWebサイトが上のほうに表示されるように工夫すること。", "abbr": "Search Engine Optimization"}, {"id": "0184", "f": "S", "sub": "マーケティング", "term": "レコメンデーション", "desc": "顧客の購入や閲覧の記録をもとに、その人が興味を持ちそうな商品を勧める仕組み。"}, {"id": "0185", "f": "S", "sub": "マーケティング", "term": "ロングテール", "desc": "インターネットでの販売で、1つ1つはあまり売れない商品でも、種類が多いので合計すると大きな売上になる現象。"}, {"id": "0186", "f": "S", "sub": "マーケティング", "term": "オムニチャネル", "desc": "店舗・Webサイト・アプリなど、あらゆる販売の窓口を連携させ、顧客がどこからでも同じように買えるようにすること。"}, {"id": "0187", "f": "S", "sub": "マーケティング", "term": "O2O", "desc": "Webやアプリ（オンライン）から、実際の店舗（オフライン）へ客を呼び込む取組み。", "abbr": "Online to Offline"}, {"id": "0188", "f": "S", "sub": "マーケティング", "term": "ワントゥワンマーケティング", "desc": "顧客一人一人の好みや買い物の記録に合わせて、別々に働きかけるマーケティング。"}, {"id": "0189", "f": "S", "sub": "マーケティング", "term": "RFM分析", "desc": "最後に買った日（Recency）・買った回数（Frequency）・買った金額（Monetary）の3つの指標で顧客を分析する手法。"}, {"id": "0190", "f": "S", "sub": "マーケティング", "term": "ダイナミックプライシング", "desc": "需要と供給の状況に合わせて、商品やサービスの価格を変えること。"}, {"id": "0191", "f": "S", "sub": "マーケティング", "term": "ペネトレーションプライシング", "desc": "新製品の価格を低くして一気に広め、市場で大きな占有率を取る価格戦略。"}, {"id": "0192", "f": "S", "sub": "マーケティング", "term": "スキミングプライシング", "desc": "新製品の価格を高くして、早いうちに開発費を回収する価格戦略。"}, {"id": "0193", "f": "S", "sub": "目標と評価", "term": "バランススコアカード", "desc": "財務・顧客・業務プロセス・学習と成長の4つの視点から、戦略の目標と実績を評価する手法。BSCとも呼ぶ。"}, {"id": "0194", "f": "S", "sub": "目標と評価", "term": "KGI", "desc": "重要目標達成指標のこと。最終的な目標を、売上高などの数値で表したもの。", "abbr": "Key Goal Indicator"}, {"id": "0195", "f": "S", "sub": "目標と評価", "term": "KPI", "desc": "重要業績評価指標のこと。最終的な目標（KGI）に向けて、途中の進み具合を測る数値。", "abbr": "Key Performance Indicator"}, {"id": "0196", "f": "S", "sub": "目標と評価", "term": "CSF", "desc": "重要成功要因のこと。目標を達成するために、特に重要となる要因。", "abbr": "Critical Success Factor"}, {"id": "0197", "f": "S", "sub": "目標と評価", "term": "バリューチェーン", "desc": "企業の活動を、購買・製造・販売などの価値を生む活動のつながりとして捉え、どこで価値が生まれているかを分析する考え方。"}, {"id": "0198", "f": "S", "sub": "目標と評価", "term": "ビジネスモデルキャンバス", "desc": "顧客・提供する価値・チャネル・収益の流れなど9つの要素で、ビジネスの仕組みを1枚の図にまとめる手法。"}, {"id": "0199", "f": "S", "sub": "経営管理システム", "term": "CRM", "desc": "顧客関係管理のこと。顧客の情報や対応の記録をまとめて管理し、顧客と長く良い関係を築く経営手法。", "abbr": "Customer Relationship Management"}, {"id": "0200", "f": "S", "sub": "経営管理システム", "term": "SCM", "desc": "供給連鎖管理のこと。原材料の調達から生産・物流・販売までを、企業の枠を超えて全体で管理する手法。", "abbr": "Supply Chain Management"}, {"id": "0201", "f": "S", "sub": "経営管理システム", "term": "SFA", "desc": "営業支援システムのこと。営業担当者の活動や商談の情報を共有・管理して、営業を効率化する。", "abbr": "Sales Force Automation"}, {"id": "0202", "f": "S", "sub": "経営管理システム", "term": "ERP", "desc": "企業資源計画のこと。会計・人事・生産・販売などの基幹業務の情報を1つにまとめて管理し、経営資源を有効に使う手法。", "abbr": "Enterprise Resource Planning"}, {"id": "0203", "f": "S", "sub": "経営管理システム", "term": "TQM", "desc": "総合的品質管理のこと。品質の向上を、組織全体で継続して進める経営手法。", "abbr": "Total Quality Management"}, {"id": "0204", "f": "S", "sub": "経営管理システム", "term": "シックスシグマ", "desc": "統計の手法を使って業務のばらつきを減らし、品質を高める経営手法。"}, {"id": "0205", "f": "S", "sub": "経営管理システム", "term": "ナレッジマネジメント", "desc": "社員が持つ知識やノウハウを共有し、組織全体で活かす経営手法。"}, {"id": "0206", "f": "S", "sub": "技術戦略", "term": "MOT", "desc": "技術経営のこと。技術を事業の成果に結び付けるための経営の考え方。", "abbr": "Management Of Technology"}, {"id": "0207", "f": "S", "sub": "技術戦略", "term": "イノベーションのジレンマ", "desc": "大企業が既存の顧客を大事にして製品の改良を続けた結果、新しい技術を持つ企業に市場を奪われてしまうこと。"}, {"id": "0208", "f": "S", "sub": "技術戦略", "term": "プロダクトイノベーション", "desc": "これまでにない新しい製品やサービスを生み出す技術革新。"}, {"id": "0209", "f": "S", "sub": "技術戦略", "term": "プロセスイノベーション", "desc": "製品を作る工程や、仕事のやり方を新しくする技術革新。"}, {"id": "0210", "f": "S", "sub": "技術戦略", "term": "オープンイノベーション", "desc": "自社だけでなく、大学や他社などの外部の技術やアイデアを組み合わせて、新しい価値を生み出すこと。"}, {"id": "0211", "f": "S", "sub": "技術戦略", "term": "魔の川", "desc": "研究の成果を、実際の製品の開発へつなげる段階で越えなければならない障壁。"}, {"id": "0212", "f": "S", "sub": "技術戦略", "term": "死の谷", "desc": "開発した製品を事業にする段階で、資金などが足りずに越えられない障壁。"}, {"id": "0213", "f": "S", "sub": "技術戦略", "term": "ダーウィンの海", "desc": "事業にした製品が、市場で他の製品との競争に勝ち残り、大きな産業になるまでの障壁。"}, {"id": "0214", "f": "S", "sub": "技術戦略", "term": "キャズム", "desc": "新しい製品が、新しいもの好きの一部の人から、一般の多くの人に広がるまでの間にある大きな溝。"}, {"id": "0215", "f": "S", "sub": "技術戦略", "term": "技術ロードマップ", "desc": "将来の技術がどのように進んでいくかを、時間の流れに沿って図にしたもの。"}, {"id": "0216", "f": "S", "sub": "技術戦略", "term": "デザイン思考", "desc": "利用者の立場に立って問題を見つけ、試作と検証を繰り返して解決策を作る考え方。"}, {"id": "0217", "f": "S", "sub": "技術戦略", "term": "リーンスタートアップ", "desc": "最小限の製品を素早く作って顧客の反応を確かめ、改良を繰り返しながら事業を作る手法。"}, {"id": "0218", "f": "S", "sub": "技術戦略", "term": "PoC", "desc": "概念実証のこと。新しいアイデアや技術が実際に実現できるかを、試作などで確かめること。", "abbr": "Proof of Concept"}, {"id": "0219", "f": "S", "sub": "技術戦略", "term": "ハッカソン", "desc": "エンジニアやデザイナーなどが集まり、短い期間で集中してアプリなどを作り、アイデアや成果を競うイベント。"}, {"id": "0220", "f": "S", "sub": "技術戦略", "term": "APIエコノミー", "desc": "企業がAPIを公開してサービスどうしをつなぎ、新しいビジネスや価値が広がっていく経済の仕組み。"}, {"id": "0221", "f": "S", "sub": "技術戦略", "term": "クラウドファンディング", "desc": "インターネットを通じて、不特定多数の人からプロジェクトの資金を集めること。"}, {"id": "0222", "f": "S", "sub": "ビジネスとIT活用", "term": "POSシステム", "desc": "商品が売れたときに、何がいつ何個売れたかの情報をその場で集めて管理する仕組み。", "abbr": "Point Of Sale"}, {"id": "0223", "f": "S", "sub": "ビジネスとIT活用", "term": "EC", "desc": "電子商取引のこと。インターネットなどのネットワークを使って、商品やサービスを売買すること。", "abbr": "Electronic Commerce"}, {"id": "0224", "f": "S", "sub": "ビジネスとIT活用", "term": "BtoB（B2B）", "desc": "企業と企業の間の取引。電子商取引では、企業どうしの受発注などを指す。"}, {"id": "0225", "f": "S", "sub": "ビジネスとIT活用", "term": "BtoC（B2C）", "desc": "企業と消費者の間の取引。電子商取引では、ネットショップなどを指す。"}, {"id": "0226", "f": "S", "sub": "ビジネスとIT活用", "term": "CtoC（C2C）", "desc": "消費者と消費者の間の取引。フリマアプリやネットオークションなど。"}, {"id": "0227", "f": "S", "sub": "ビジネスとIT活用", "term": "EDI", "desc": "電子データ交換のこと。企業の間で、受発注などの取引のデータを決まった形式でやり取りすること。", "abbr": "Electronic Data Interchange"}, {"id": "0228", "f": "S", "sub": "ビジネスとIT活用", "term": "フィンテック（FinTech）", "desc": "金融（Finance）と技術（Technology）を組み合わせた言葉。ITを使った新しい金融サービス。"}, {"id": "0229", "f": "S", "sub": "ビジネスとIT活用", "term": "キャッシュレス決済", "desc": "現金を使わずに、クレジットカード・電子マネー・QRコードなどで支払うこと。"}, {"id": "0230", "f": "S", "sub": "ビジネスとIT活用", "term": "電子マネー", "desc": "お金の価値をICカードやスマートフォンなどにデータとして記録し、支払いに使うもの。"}, {"id": "0231", "f": "S", "sub": "ビジネスとIT活用", "term": "ICカード", "desc": "ICチップを埋め込んだカード。磁気カードより多くの情報を記録でき、偽造されにくい。"}, {"id": "0232", "f": "S", "sub": "ビジネスとIT活用", "term": "RFID", "desc": "電波を使って、ICタグの情報を触れずに読み書きする技術。商品の管理などに使う。", "abbr": "Radio Frequency Identification"}, {"id": "0233", "f": "S", "sub": "ビジネスとIT活用", "term": "エスクローサービス", "desc": "取引の間に第三者が入り、商品の受け取りが確認されるまで代金を預かって、安全に取引できるようにする仕組み。"}, {"id": "0234", "f": "S", "sub": "ビジネスとIT活用", "term": "クラウドソーシング", "desc": "インターネットを通じて、不特定多数の人に仕事を依頼すること。"}, {"id": "0235", "f": "S", "sub": "ビジネスとIT活用", "term": "シェアリングエコノミー", "desc": "個人が持つ車・部屋・スキルなどを、インターネットを通じて他の人と共有したり貸し借りしたりする経済の仕組み。"}, {"id": "0236", "f": "S", "sub": "ビジネスとIT活用", "term": "GPS", "desc": "人工衛星からの電波を使って、地球上の現在の位置を調べる仕組み。", "abbr": "Global Positioning System"}, {"id": "0237", "f": "S", "sub": "ビジネスとIT活用", "term": "デジタルサイネージ", "desc": "ディスプレイを使って、駅や店舗などで映像や情報を表示する電子看板。"}, {"id": "0238", "f": "S", "sub": "ビジネスとIT活用", "term": "トレーサビリティ", "desc": "製品や食品が、いつ・どこで・どのように作られ、運ばれたかを追跡できること。"}, {"id": "0239", "f": "S", "sub": "ビジネスとIT活用", "term": "CAD", "desc": "コンピュータを使って、製品や建物などの設計図を作ること。", "abbr": "Computer Aided Design"}, {"id": "0240", "f": "S", "sub": "ビジネスとIT活用", "term": "CAM", "desc": "CADで作った設計データを使い、コンピュータで工作機械を動かして製造すること。", "abbr": "Computer Aided Manufacturing"}, {"id": "0241", "f": "S", "sub": "ビジネスとIT活用", "term": "FA", "desc": "工場の生産工程を、コンピュータやロボットで自動化すること。", "abbr": "Factory Automation"}, {"id": "0242", "f": "S", "sub": "ビジネスとIT活用", "term": "CIM", "desc": "設計・製造・販売などの情報をコンピュータでつなぎ、生産活動の全体を管理すること。", "abbr": "Computer Integrated Manufacturing"}, {"id": "0243", "f": "S", "sub": "ビジネスとIT活用", "term": "MRP", "desc": "資材所要量計画のこと。生産計画から、必要な部品や材料の量と時期を計算し、発注を管理する手法。", "abbr": "Material Requirements Planning"}, {"id": "0244", "f": "S", "sub": "ビジネスとIT活用", "term": "セル生産方式", "desc": "1人または少人数のチームが、部品の取付けから完成までのすべての工程を受け持つ生産方式。多品種少量の生産に向く。"}, {"id": "0245", "f": "S", "sub": "ビジネスとIT活用", "term": "組込みシステム", "desc": "家電や自動車などの機器に組み込まれ、その機器を制御するためのコンピュータシステム。"}, {"id": "0246", "f": "S", "sub": "ビジネスとIT活用", "term": "スマートファクトリー", "desc": "IoTやAIを使って、工場の機械や設備の情報をつなぎ、生産を効率化・自動化した工場。"}, {"id": "0247", "f": "S", "sub": "ビジネスとIT活用", "term": "インダストリー4.0", "desc": "IoTやAIを使って製造業を大きく変えようとする考え方。ドイツが進めた取組みが始まり。"}, {"id": "0248", "f": "S", "sub": "ビジネスとIT活用", "term": "Society 5.0", "desc": "日本が目指す未来の社会の姿。仮想空間（サイバー空間）と現実の空間を高度に組み合わせて、経済の発展と社会の課題の解決を両立させる社会。"}, {"id": "0249", "f": "S", "sub": "ビジネスとIT活用", "term": "スマートシティ", "desc": "ITやデータを使って、交通・エネルギー・防災などの都市の課題を解決し、暮らしやすくした都市。"}, {"id": "0250", "f": "S", "sub": "ビジネスとIT活用", "term": "MaaS", "desc": "電車・バス・タクシーなどのさまざまな交通手段を1つのサービスとしてまとめ、検索・予約・支払いを一度にできるようにすること。", "abbr": "Mobility as a Service"}, {"id": "0251", "f": "S", "sub": "ビジネスとIT活用", "term": "デジタルツイン", "desc": "現実の世界の物や環境をデータで仮想空間に再現し、分析や予測に使う技術。"}, {"id": "0252", "f": "S", "sub": "ビジネスとIT活用", "term": "サイバーフィジカルシステム", "desc": "現実の世界のデータをセンサで集め、仮想空間で分析した結果を現実の世界に役立てる仕組み。CPSとも呼ぶ。"}, {"id": "0253", "f": "S", "sub": "ビジネスとIT活用", "term": "ドローン", "desc": "遠隔操作や自動操縦で飛ぶ、小型の無人の航空機。"}, {"id": "0254", "f": "S", "sub": "システム戦略", "term": "DX", "desc": "デジタルトランスフォーメーションのこと。データとデジタル技術を使って、製品・サービスやビジネスのやり方、組織そのものを変革し、競争で優位に立つこと。", "abbr": "Digital Transformation"}, {"id": "0255", "f": "S", "sub": "システム戦略", "term": "BPR", "desc": "業務の流れや組織を根本から見直して、作り直すこと。", "abbr": "Business Process Reengineering"}, {"id": "0256", "f": "S", "sub": "システム戦略", "term": "BPM", "desc": "業務の流れを分析・設計・実行・改善するサイクルを繰り返し、業務を継続して良くしていく手法。", "abbr": "Business Process Management"}, {"id": "0257", "f": "S", "sub": "システム戦略", "term": "BPO", "desc": "企業の業務の一部（経理・人事など）を、まとめて外部の会社に任せること。", "abbr": "Business Process Outsourcing"}, {"id": "0258", "f": "S", "sub": "システム戦略", "term": "RPA", "desc": "これまで人がパソコンで行っていた定型的な作業を、ソフトウェアのロボットで自動化すること。", "abbr": "Robotic Process Automation"}, {"id": "0259", "f": "S", "sub": "システム戦略", "term": "エンタープライズアーキテクチャ", "desc": "組織全体の業務とシステムを統一した方法で整理・分析し、全体を最適化するための手法。EAとも呼ぶ。"}, {"id": "0260", "f": "S", "sub": "システム戦略", "term": "SOA", "desc": "システムの機能を「サービス」という部品として作り、それらを組み合わせてシステムを作る考え方。", "abbr": "Service Oriented Architecture"}, {"id": "0261", "f": "S", "sub": "システム戦略", "term": "クラウドコンピューティング", "desc": "サーバやソフトウェアなどを、インターネットを通じてサービスとして、必要な分だけ使う形態。"}, {"id": "0262", "f": "S", "sub": "システム戦略", "term": "SaaS", "desc": "インターネットを通じて、ソフトウェア（アプリケーション）の機能をサービスとして提供する形態。", "abbr": "Software as a Service"}, {"id": "0263", "f": "S", "sub": "システム戦略", "term": "PaaS", "desc": "アプリケーションを動かすための基盤（OSやデータベースなど）を、インターネットを通じて提供する形態。", "abbr": "Platform as a Service"}, {"id": "0264", "f": "S", "sub": "システム戦略", "term": "IaaS", "desc": "サーバ・ストレージ・ネットワークなどの設備を、インターネットを通じて提供する形態。", "abbr": "Infrastructure as a Service"}, {"id": "0265", "f": "S", "sub": "システム戦略", "term": "オンプレミス", "desc": "サーバやソフトウェアなどを、自社の建物の中に置いて、自社で運用する形態。"}, {"id": "0266", "f": "S", "sub": "システム戦略", "term": "ハウジング", "desc": "事業者の施設（データセンタ）に、自社のサーバなどの機器を置かせてもらうサービス。"}, {"id": "0267", "f": "S", "sub": "システム戦略", "term": "ホスティング", "desc": "事業者が用意したサーバを借りて、自社のシステムやWebサイトを運用するサービス。"}, {"id": "0268", "f": "S", "sub": "システム戦略", "term": "グループウェア", "desc": "スケジュール・掲示板・ファイル共有など、組織の中で情報を共有して共同作業をするためのソフトウェア。"}, {"id": "0269", "f": "S", "sub": "システム戦略", "term": "ワークフローシステム", "desc": "申請や承認などの業務の流れを電子化し、書類を自動で次の担当者に回す仕組み。"}, {"id": "0270", "f": "S", "sub": "システム戦略", "term": "BYOD", "desc": "社員が個人で持っているスマートフォンやパソコンを、仕事に使うこと。", "abbr": "Bring Your Own Device"}, {"id": "0271", "f": "S", "sub": "システム戦略", "term": "シャドーIT", "desc": "会社が許可していない機器やクラウドサービスを、社員が勝手に仕事で使うこと。"}, {"id": "0272", "f": "S", "sub": "システム戦略", "term": "情報リテラシ", "desc": "情報機器を使いこなし、必要な情報を集め、正しく判断して活用する能力。"}, {"id": "0273", "f": "S", "sub": "システム戦略", "term": "デジタルデバイド", "desc": "ITを使える人と使えない人の間に生まれる、情報や機会の格差。"}, {"id": "0274", "f": "S", "sub": "システム戦略", "term": "オープンデータ", "desc": "誰でも自由に使い、加工し、再配布できる形で公開されたデータ。国や自治体などが公開している。"}, {"id": "0275", "f": "S", "sub": "システム戦略", "term": "ゲーミフィケーション", "desc": "ポイントやランキングなどのゲームの要素を、ゲーム以外の活動に取り入れて、やる気を高めること。"}, {"id": "0276", "f": "S", "sub": "システム企画", "term": "システム化構想", "desc": "経営戦略に合わせて、どの業務をどのようにシステム化するかの全体の方針を決めること。"}, {"id": "0277", "f": "S", "sub": "システム企画", "term": "要件定義", "desc": "システムや業務に求められる機能や性能などの要件を、はっきりさせて決めること。"}, {"id": "0278", "f": "S", "sub": "システム企画", "term": "機能要件", "desc": "システムが持つべき機能（どんな処理をするか）についての要件。"}, {"id": "0279", "f": "S", "sub": "システム企画", "term": "非機能要件", "desc": "性能・信頼性・セキュリティ・使いやすさなど、機能以外にシステムに求められる要件。"}, {"id": "0280", "f": "S", "sub": "システム企画", "term": "ベンダ", "desc": "製品やサービスを売る会社。システム開発では、開発を請け負う会社を指すことが多い。"}, {"id": "0281", "f": "S", "sub": "システム企画", "term": "RFI", "desc": "情報提供依頼書のこと。システムを発注する前に、ベンダに技術や製品の情報の提供を求める文書。", "abbr": "Request For Information"}, {"id": "0282", "f": "S", "sub": "システム企画", "term": "RFP", "desc": "提案依頼書のこと。発注する側がシステムの要件などを示し、ベンダに具体的な提案を求める文書。", "abbr": "Request For Proposal"}, {"id": "0283", "f": "S", "sub": "システム企画", "term": "ROI", "desc": "投資利益率のこと。投資した金額に対して、どれだけの利益が得られたかを示す指標。", "abbr": "Return On Investment"}, {"id": "0284", "f": "S", "sub": "システム企画", "term": "グリーン調達", "desc": "環境への負荷が少ない製品やサービスを、優先して購入すること。"}, {"id": "0285", "f": "M", "sub": "システム開発", "term": "外部設計", "desc": "利用者から見える部分（画面・帳票・操作の方法など）を設計すること。"}, {"id": "0286", "f": "M", "sub": "システム開発", "term": "内部設計", "desc": "外部設計をもとに、システムの内部の構造や処理の方法を設計すること。"}, {"id": "0287", "f": "M", "sub": "システム開発", "term": "レビュー", "desc": "設計書やプログラムなどを関係者で確認し、誤りや問題点を早い段階で見つけること。"}, {"id": "0288", "f": "M", "sub": "システム開発", "term": "単体テスト", "desc": "プログラムを構成する部品（モジュール）を1つずつ、正しく動くかを確かめるテスト。"}, {"id": "0289", "f": "M", "sub": "システム開発", "term": "結合テスト", "desc": "複数のモジュールを組み合わせて、モジュールの間のデータの受け渡しなどが正しいかを確かめるテスト。"}, {"id": "0290", "f": "M", "sub": "システム開発", "term": "システムテスト", "desc": "システム全体が、要件どおりの機能や性能を満たしているかを、開発する側が確かめるテスト。"}, {"id": "0291", "f": "M", "sub": "システム開発", "term": "運用テスト", "desc": "実際の業務と同じ環境や手順でシステムを動かし、業務に使えるかを利用者が確かめるテスト。"}, {"id": "0292", "f": "M", "sub": "システム開発", "term": "受入れテスト", "desc": "発注した側が、納品されたシステムが要件を満たしているかを確かめ、受け取るかどうかを判断するテスト。"}, {"id": "0293", "f": "M", "sub": "システム開発", "term": "回帰テスト", "desc": "プログラムを修正したときに、修正していない部分に悪い影響が出ていないかを確かめるテスト。リグレッションテストとも呼ぶ。"}, {"id": "0294", "f": "M", "sub": "システム開発", "term": "ブラックボックステスト", "desc": "プログラムの中身は見ずに、入力に対して正しい出力が得られるかを確かめるテスト。"}, {"id": "0295", "f": "M", "sub": "システム開発", "term": "ホワイトボックステスト", "desc": "プログラムの中身（内部の構造や処理の流れ）に注目して、命令や分岐が正しく動くかを確かめるテスト。"}, {"id": "0296", "f": "M", "sub": "システム開発", "term": "信頼度成長曲線", "desc": "テストの時間と、見つかったバグの数の累計の関係を表したグラフ。バグが出尽くしてくると、曲線が平らになる。"}, {"id": "0297", "f": "M", "sub": "システム開発", "term": "ソフトウェア保守", "desc": "システムを使い始めた後に、不具合を直したり、環境の変化に合わせて変更したりすること。"}, {"id": "0298", "f": "M", "sub": "システム開発", "term": "DFD", "desc": "データの流れ・処理・データの保存場所・外部との出入りを、記号で表した図。データフローダイアグラム。", "abbr": "Data Flow Diagram"}, {"id": "0299", "f": "M", "sub": "システム開発", "term": "UML", "desc": "オブジェクト指向での設計を図で表すための、統一された表記法。クラス図やユースケース図などがある。", "abbr": "Unified Modeling Language"}, {"id": "0300", "f": "M", "sub": "システム開発", "term": "オブジェクト指向", "desc": "データと、それを扱う手続きを1つにまとめた「オブジェクト」を単位として、システムを作る考え方。"}, {"id": "0301", "f": "M", "sub": "開発の進め方", "term": "ウォーターフォールモデル", "desc": "要件定義・設計・プログラミング・テストなどの工程を順番に進め、原則として前の工程に戻らない開発手法。"}, {"id": "0302", "f": "M", "sub": "開発の進め方", "term": "プロトタイピング", "desc": "早い段階で試作品（プロトタイプ）を作って利用者に見てもらい、要求を確かめながら進める開発手法。"}, {"id": "0303", "f": "M", "sub": "開発の進め方", "term": "スパイラルモデル", "desc": "システムをいくつかの部分に分け、設計・開発・評価を繰り返しながら少しずつ完成させる開発手法。"}, {"id": "0304", "f": "M", "sub": "開発の進め方", "term": "アジャイル", "desc": "短い期間で開発とリリースを繰り返し、変化に素早く対応しながら作っていく開発手法の総称。"}, {"id": "0305", "f": "M", "sub": "開発の進め方", "term": "スクラム", "desc": "アジャイル開発の手法の1つ。チームで短い期間（スプリント）ごとに、計画・開発・振り返りを繰り返す。"}, {"id": "0306", "f": "M", "sub": "開発の進め方", "term": "XP（エクストリームプログラミング）", "desc": "アジャイル開発の手法の1つ。テスト駆動開発やペアプログラミングなど、開発のための実践のやり方を定めている。"}, {"id": "0307", "f": "M", "sub": "開発の進め方", "term": "テスト駆動開発", "desc": "プログラムを書く前にテストを作り、そのテストに合格するようにプログラムを書いていく開発のやり方。"}, {"id": "0308", "f": "M", "sub": "開発の進め方", "term": "ペアプログラミング", "desc": "2人1組で、1人がプログラムを書き、もう1人がそれを確認しながら一緒に開発するやり方。"}, {"id": "0309", "f": "M", "sub": "開発の進め方", "term": "リファクタリング", "desc": "プログラムの外から見た動きは変えずに、中の構造を分かりやすく整理し直すこと。"}, {"id": "0310", "f": "M", "sub": "開発の進め方", "term": "DevOps", "desc": "開発（Development）と運用（Operations）の担当者が協力し、システムの開発から運用までを素早く進める考え方。"}, {"id": "0311", "f": "M", "sub": "開発の進め方", "term": "リバースエンジニアリング", "desc": "既にあるソフトウェアを分析して、仕組みや設計の情報を取り出すこと。"}, {"id": "0312", "f": "M", "sub": "開発の進め方", "term": "共通フレーム", "desc": "ソフトウェアの開発や取引で使う作業の内容や用語を、関係者の間でそろえるための枠組み。"}, {"id": "0313", "f": "M", "sub": "開発の進め方", "term": "CMMI", "desc": "組織のソフトウェア開発の能力（プロセスの成熟度）を、5つの段階で評価するモデル。", "abbr": "Capability Maturity Model Integration"}, {"id": "0314", "f": "M", "sub": "プロジェクトマネジメント", "term": "プロジェクト", "desc": "決まった目的を達成するために、期間を区切って行う一度きりの取組み。"}, {"id": "0315", "f": "M", "sub": "プロジェクトマネジメント", "term": "プロジェクトマネージャ", "desc": "プロジェクトの責任者として計画を立て、メンバーをまとめ、目標を達成させる人。"}, {"id": "0316", "f": "M", "sub": "プロジェクトマネジメント", "term": "プロジェクト憲章", "desc": "プロジェクトを正式に認め、目的や大まかな範囲、プロジェクトマネージャの権限などを書いた文書。"}, {"id": "0317", "f": "M", "sub": "プロジェクトマネジメント", "term": "PMBOK", "desc": "プロジェクトマネジメントの知識や手法を体系的にまとめたガイド。米国のPMIが発行している。", "abbr": "Project Management Body of Knowledge"}, {"id": "0318", "f": "M", "sub": "プロジェクトマネジメント", "term": "スコープ", "desc": "プロジェクトで作るもの（成果物）と、そのために必要な作業の範囲。"}, {"id": "0319", "f": "M", "sub": "プロジェクトマネジメント", "term": "WBS", "desc": "プロジェクトの作業を、管理しやすい大きさまで階層的に細かく分けたもの。", "abbr": "Work Breakdown Structure"}, {"id": "0320", "f": "M", "sub": "プロジェクトマネジメント", "term": "ガントチャート", "desc": "作業を縦に並べ、横軸の時間に沿って、それぞれの作業の予定や実績を横棒で表した図。"}, {"id": "0321", "f": "M", "sub": "プロジェクトマネジメント", "term": "アローダイアグラム", "desc": "作業の順番と関係を、矢印と結合点で表した図。PERT図とも呼ぶ。"}, {"id": "0322", "f": "M", "sub": "プロジェクトマネジメント", "term": "クリティカルパス", "desc": "作業の流れのうち、最も時間がかかる経路。この経路の上の作業が遅れると、全体が遅れる。"}, {"id": "0323", "f": "M", "sub": "プロジェクトマネジメント", "term": "マイルストーン", "desc": "プロジェクトの途中に置く、重要な節目となる時点（例: 設計の完了）。"}, {"id": "0324", "f": "M", "sub": "プロジェクトマネジメント", "term": "EVM", "desc": "作業の価値を金額に置き換えて、計画・実績・出来高を比べ、プロジェクトの進み具合とコストを管理する手法。", "abbr": "Earned Value Management"}, {"id": "0325", "f": "M", "sub": "プロジェクトマネジメント", "term": "ファンクションポイント法", "desc": "ソフトウェアの機能の数や複雑さをもとに、開発の規模を見積もる方法。"}, {"id": "0326", "f": "M", "sub": "プロジェクトマネジメント", "term": "類推見積法", "desc": "過去の似たプロジェクトの実績をもとに、規模や費用を見積もる方法。"}, {"id": "0327", "f": "M", "sub": "プロジェクトマネジメント", "term": "クラッシング", "desc": "要員を増やすなど費用をかけて、クリティカルパスの上の作業の期間を縮めること。"}, {"id": "0328", "f": "M", "sub": "プロジェクトマネジメント", "term": "ファストトラッキング", "desc": "本来は順番に行う作業の一部を並行して行うことで、全体の期間を縮めること。"}, {"id": "0329", "f": "M", "sub": "サービスマネジメント", "term": "ITサービスマネジメント", "desc": "利用者に合ったITサービスを、効率よく安定して提供するための管理の仕組み。"}, {"id": "0330", "f": "M", "sub": "サービスマネジメント", "term": "ITIL", "desc": "ITサービスマネジメントの成功事例（ベストプラクティス）をまとめたガイドブック。", "abbr": "Information Technology Infrastructure Library"}, {"id": "0331", "f": "M", "sub": "サービスマネジメント", "term": "SLA", "desc": "サービスレベル合意書のこと。サービスの提供者と利用者の間で、サービスの内容や品質の目標を取り決めたもの。", "abbr": "Service Level Agreement"}, {"id": "0332", "f": "M", "sub": "サービスマネジメント", "term": "SLM", "desc": "サービスレベル管理のこと。SLAで決めたサービスの品質を守るため、計画・実行・確認・改善を続ける活動。", "abbr": "Service Level Management"}, {"id": "0333", "f": "M", "sub": "サービスマネジメント", "term": "サービスデスク", "desc": "利用者からの問合せや障害の連絡を、一か所で受け付ける窓口。ヘルプデスクとも呼ぶ。"}, {"id": "0334", "f": "M", "sub": "サービスマネジメント", "term": "インシデント管理", "desc": "サービスが止まるなどの出来事（インシデント）が起きたときに、できるだけ早くサービスを元に戻す活動。"}, {"id": "0335", "f": "M", "sub": "サービスマネジメント", "term": "問題管理", "desc": "インシデントの根本的な原因を突き止め、再発を防ぐ活動。"}, {"id": "0336", "f": "M", "sub": "サービスマネジメント", "term": "変更管理", "desc": "システムの変更を事前に評価・承認し、安全に行えるように管理する活動。"}, {"id": "0337", "f": "M", "sub": "サービスマネジメント", "term": "リリース管理", "desc": "承認された変更を、本番の環境へ正しく導入（リリース）する活動。"}, {"id": "0338", "f": "M", "sub": "サービスマネジメント", "term": "構成管理", "desc": "システムを構成する機器やソフトウェアなど（構成品目）の情報を、正確に記録・管理する活動。"}, {"id": "0339", "f": "M", "sub": "サービスマネジメント", "term": "エスカレーション", "desc": "自分で解決できない問題を、上位の担当者や専門の部署に引き継いだり、報告したりすること。"}, {"id": "0340", "f": "M", "sub": "サービスマネジメント", "term": "FAQ", "desc": "よくある質問と、その回答をまとめたもの。", "abbr": "Frequently Asked Questions"}, {"id": "0341", "f": "M", "sub": "サービスマネジメント", "term": "チャットボット", "desc": "文字や音声で話しかけると、自動で応答するプログラム。問合せの窓口などで使う。"}, {"id": "0342", "f": "M", "sub": "サービスマネジメント", "term": "ファシリティマネジメント", "desc": "建物・設備・電源・空調などの施設を、最適な状態に保つように管理すること。"}, {"id": "0343", "f": "M", "sub": "サービスマネジメント", "term": "UPS", "desc": "無停電電源装置のこと。停電したときに、しばらくの間電気を送り続けて機器を守る装置。", "abbr": "Uninterruptible Power Supply"}, {"id": "0344", "f": "M", "sub": "システム監査", "term": "システム監査", "desc": "独立した立場の監査人が、情報システムが適切に管理・運用されているかを点検・評価し、改善のための助言をすること。"}, {"id": "0345", "f": "M", "sub": "システム監査", "term": "システム監査人", "desc": "システム監査を行う人。監査される部門から独立した立場であることが求められる。"}, {"id": "0346", "f": "M", "sub": "システム監査", "term": "監査証拠", "desc": "監査人の意見の裏付けとなる資料や記録。"}, {"id": "0347", "f": "M", "sub": "システム監査", "term": "監査証跡", "desc": "システムの処理の流れを、後からたどって確かめられるようにした記録。ログなど。"}, {"id": "0348", "f": "M", "sub": "システム監査", "term": "フォローアップ", "desc": "監査で指摘した点が改善されているかを、後で確かめること。"}, {"id": "0349", "f": "M", "sub": "システム監査", "term": "内部統制", "desc": "業務を適正に行うために、企業の中に作るルールや仕組み。不正やミスを防ぐ。"}, {"id": "0350", "f": "M", "sub": "システム監査", "term": "職務分掌", "desc": "1つの業務を1人に任せきりにせず、担当や権限を分けて、不正やミスを防ぐこと。"}, {"id": "0351", "f": "M", "sub": "システム監査", "term": "モニタリング", "desc": "内部統制がきちんと働いているかを、継続して監視・評価すること。"}, {"id": "0352", "f": "M", "sub": "システム監査", "term": "ITガバナンス", "desc": "経営者が主導してIT戦略を立て、その実行を管理・監視して、ITを経営に役立てる仕組み。"}, {"id": "0353", "f": "T", "sub": "基礎理論", "term": "2進数", "desc": "0と1の2つの数字だけで数を表す方法。コンピュータの内部は、この形で情報を扱う。"}, {"id": "0354", "f": "T", "sub": "基礎理論", "term": "16進数", "desc": "0〜9とA〜Fの16種類の記号で数を表す方法。2進数の4桁が、16進数の1桁に当たる。"}, {"id": "0355", "f": "T", "sub": "基礎理論", "term": "基数変換", "desc": "ある進数で表された数を、別の進数の表し方に変えること。"}, {"id": "0356", "f": "T", "sub": "基礎理論", "term": "ビット", "desc": "コンピュータが扱う情報の最小の単位。0か1のどちらかを表す。"}, {"id": "0357", "f": "T", "sub": "基礎理論", "term": "バイト", "desc": "情報の量の単位。1バイトは8ビット。"}, {"id": "0358", "f": "T", "sub": "基礎理論", "term": "単位の接頭語", "desc": "大きな量や小さな量を表すために単位の前に付ける語。キロ（10の3乗）・メガ（10の6乗）・ギガ（10の9乗）・テラ（10の12乗）、ミリ（10の−3乗）・マイクロ（10の−6乗）・ナノ（10の−9乗）など。"}, {"id": "0359", "f": "T", "sub": "基礎理論", "term": "論理積（AND）", "desc": "2つの入力がどちらも1（真）のときだけ、1になる論理演算。"}, {"id": "0360", "f": "T", "sub": "基礎理論", "term": "論理和（OR）", "desc": "2つの入力のどちらか一方でも1（真）なら、1になる論理演算。"}, {"id": "0361", "f": "T", "sub": "基礎理論", "term": "否定（NOT）", "desc": "入力の値を反対にする論理演算。1なら0に、0なら1にする。"}, {"id": "0362", "f": "T", "sub": "基礎理論", "term": "排他的論理和（XOR）", "desc": "2つの入力が異なるときだけ1になり、同じときは0になる論理演算。"}, {"id": "0363", "f": "T", "sub": "基礎理論", "term": "真理値表", "desc": "論理演算で、入力のすべての組合せと、そのときの出力をまとめた表。"}, {"id": "0364", "f": "T", "sub": "基礎理論", "term": "ベン図", "desc": "複数の集合の関係を、円などの図形の重なりで表した図。"}, {"id": "0365", "f": "T", "sub": "基礎理論", "term": "平均値", "desc": "データの値をすべて足して、データの個数で割った値。"}, {"id": "0366", "f": "T", "sub": "基礎理論", "term": "中央値（メジアン）", "desc": "データを小さい順に並べたときに、ちょうど真ん中にくる値。"}, {"id": "0367", "f": "T", "sub": "基礎理論", "term": "最頻値（モード）", "desc": "データの中で、最も多く出てくる値。"}, {"id": "0368", "f": "T", "sub": "基礎理論", "term": "分散", "desc": "データのばらつきの大きさを表す値。各データと平均との差を2乗して、それを平均したもの。"}, {"id": "0369", "f": "T", "sub": "基礎理論", "term": "標準偏差", "desc": "分散の正の平方根。データが平均からどれくらい散らばっているかを、元のデータと同じ単位で表す。"}, {"id": "0370", "f": "T", "sub": "基礎理論", "term": "正規分布", "desc": "平均を中心に、左右対称の山の形になるデータの分布。身長や試験の点数などが、これに近い形になる。"}, {"id": "0371", "f": "T", "sub": "基礎理論", "term": "順列", "desc": "いくつかのものから決まった数を取り出し、順番を考えて並べる方法の数。"}, {"id": "0372", "f": "T", "sub": "基礎理論", "term": "組合せ", "desc": "いくつかのものから決まった数を取り出すときの、順番を考えない選び方の数。"}, {"id": "0373", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "アルゴリズム", "desc": "問題を解決するための、決まった手順。"}, {"id": "0374", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "フローチャート", "desc": "処理の手順を、決められた記号と矢印で表した図。流れ図とも呼ぶ。"}, {"id": "0375", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "変数", "desc": "プログラムの中で、データを一時的に入れておく箱のようなもの。名前を付けて使う。"}, {"id": "0376", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "配列", "desc": "同じ種類のデータを並べて、番号（添字）で1つずつ取り出せるようにしたデータ構造。"}, {"id": "0377", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "スタック", "desc": "最後に入れたデータを、最初に取り出すデータ構造。後入れ先出し（LIFO）。"}, {"id": "0378", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "キュー", "desc": "最初に入れたデータを、最初に取り出すデータ構造。先入れ先出し（FIFO）。"}, {"id": "0379", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "線形探索", "desc": "データを先頭から1つずつ順番に調べて、目的のデータを探す方法。"}, {"id": "0380", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "二分探索", "desc": "整列したデータの真ん中の値と比べて、探す範囲を半分ずつに絞っていく探索の方法。"}, {"id": "0381", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "ソート", "desc": "データを決まった順番（小さい順・大きい順など）に並べ替えること。整列とも呼ぶ。"}, {"id": "0382", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "プログラム言語", "desc": "コンピュータへの命令を書くための言語。Python・Java・C言語など。"}, {"id": "0383", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "Python", "desc": "読み書きしやすい文法が特徴のプログラム言語。AIやデータ分析の分野で広く使われている。"}, {"id": "0384", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "JavaScript", "desc": "Webページに動きを付けるためによく使われるプログラム言語。ブラウザの中で動く。"}, {"id": "0385", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "Java", "desc": "オブジェクト指向のプログラム言語。いろいろなOSの上で、同じプログラムを動かしやすい。"}, {"id": "0386", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "マークアップ言語", "desc": "文章の構造や見た目を、タグなどの記号で示すための言語。HTMLやXMLなど。"}, {"id": "0387", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "HTML", "desc": "Webページを作るためのマークアップ言語。見出しや段落、リンクなどをタグで示す。", "abbr": "HyperText Markup Language"}, {"id": "0388", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "XML", "desc": "利用者が独自のタグを決めて、データの意味や構造を表せるマークアップ言語。", "abbr": "Extensible Markup Language"}, {"id": "0389", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "CSS", "desc": "Webページの文字の大きさや色、配置などの見た目を指定するための言語。", "abbr": "Cascading Style Sheets"}, {"id": "0390", "f": "T", "sub": "アルゴリズムとプログラミング", "term": "JSON", "desc": "データをやり取りするための、文字で書かれた軽いデータ形式。JavaScriptの書き方がもとになっている。", "abbr": "JavaScript Object Notation"}, {"id": "0391", "f": "T", "sub": "AI・データ活用", "term": "AI", "desc": "人工知能のこと。人間の知的な働き（学習・推論・判断など）を、コンピュータで実現する技術。", "abbr": "Artificial Intelligence"}, {"id": "0392", "f": "T", "sub": "AI・データ活用", "term": "機械学習", "desc": "コンピュータが大量のデータからパターンやルールを学び、予測や判断ができるようになる技術。"}, {"id": "0393", "f": "T", "sub": "AI・データ活用", "term": "ディープラーニング", "desc": "人間の脳の神経回路をまねたニューラルネットワークを、何層も重ねて使う機械学習。深層学習とも呼ぶ。"}, {"id": "0394", "f": "T", "sub": "AI・データ活用", "term": "ニューラルネットワーク", "desc": "人間の脳の神経細胞のつながりをまねて作った、計算の仕組み。"}, {"id": "0395", "f": "T", "sub": "AI・データ活用", "term": "教師あり学習", "desc": "正解（ラベル）の付いたデータを使って学習させる、機械学習の方法。"}, {"id": "0396", "f": "T", "sub": "AI・データ活用", "term": "教師なし学習", "desc": "正解の付いていないデータから、データの特徴やグループを見つけ出す、機械学習の方法。"}, {"id": "0397", "f": "T", "sub": "AI・データ活用", "term": "強化学習", "desc": "試行錯誤を繰り返し、より多くの報酬が得られる行動を学んでいく、機械学習の方法。"}, {"id": "0398", "f": "T", "sub": "AI・データ活用", "term": "過学習", "desc": "機械学習で、学習に使ったデータに合わせすぎて、新しいデータに対してはうまく予測できなくなること。"}, {"id": "0399", "f": "T", "sub": "AI・データ活用", "term": "アノテーション", "desc": "機械学習に使うデータに、正解や意味を表すラベル（タグ）を付ける作業。"}, {"id": "0400", "f": "T", "sub": "AI・データ活用", "term": "生成AI", "desc": "学習したデータをもとに、文章・画像・音声などを新しく作り出すAI。"}, {"id": "0401", "f": "T", "sub": "AI・データ活用", "term": "大規模言語モデル（LLM）", "desc": "大量の文章を学習して、人間のように自然な文章を理解したり作ったりできるAIのモデル。"}, {"id": "0402", "f": "T", "sub": "AI・データ活用", "term": "プロンプト", "desc": "生成AIに対して出す、指示や質問の文。"}, {"id": "0403", "f": "T", "sub": "AI・データ活用", "term": "ハルシネーション", "desc": "生成AIが、事実とは異なる内容を、もっともらしく答えてしまうこと。"}, {"id": "0404", "f": "T", "sub": "AI・データ活用", "term": "AIのバイアス", "desc": "AIの判断に表れる偏り。学習に使ったデータに偏りがあると、不公平な結果につながることがある。"}, {"id": "0405", "f": "T", "sub": "AI・データ活用", "term": "説明可能なAI（XAI）", "desc": "AIがなぜその結果を出したのかを、人間が理解できるように説明できるようにしたAI。"}, {"id": "0406", "f": "T", "sub": "AI・データ活用", "term": "人間中心のAI社会原則", "desc": "AIを人間のために役立てるため、AIの社会での使い方について日本政府がまとめた基本的な原則。"}, {"id": "0407", "f": "T", "sub": "AI・データ活用", "term": "ビッグデータ", "desc": "量が非常に多く、種類もさまざまで、絶えず生まれ続けるデータの集まり。分析して新しい価値を生み出すのに使う。"}, {"id": "0408", "f": "T", "sub": "AI・データ活用", "term": "データサイエンス", "desc": "統計学や情報科学などを使って、データから役に立つ知識を引き出す学問や手法。"}, {"id": "0409", "f": "T", "sub": "AI・データ活用", "term": "データサイエンティスト", "desc": "データを分析して、ビジネスなどの課題の解決に役立てる専門家。"}, {"id": "0410", "f": "T", "sub": "AI・データ活用", "term": "データマイニング", "desc": "大量のデータを分析して、これまで知られていなかった規則性や関係を見つけ出すこと。"}, {"id": "0411", "f": "T", "sub": "AI・データ活用", "term": "テキストマイニング", "desc": "文章のデータを分析して、よく出る言葉や言葉どうしの関係などから、役に立つ情報を見つけ出すこと。"}, {"id": "0412", "f": "T", "sub": "AI・データ活用", "term": "BIツール", "desc": "企業にたまったデータを集計・分析し、経営の判断に役立つようにグラフなどで見せるツール。", "abbr": "Business Intelligence"}, {"id": "0413", "f": "T", "sub": "コンピュータ", "term": "コンピュータの五大装置", "desc": "コンピュータを構成する、入力・出力・記憶・演算・制御の5つの装置。"}, {"id": "0414", "f": "T", "sub": "コンピュータ", "term": "CPU", "desc": "中央処理装置のこと。プログラムの命令を読み取り、計算や制御を行うコンピュータの中心となる装置。", "abbr": "Central Processing Unit"}, {"id": "0415", "f": "T", "sub": "コンピュータ", "term": "クロック周波数", "desc": "CPUが動作するタイミングを決める信号が、1秒間に何回出るかを表す値。単位はHz（ヘルツ）。高いほど処理が速い傾向がある。"}, {"id": "0416", "f": "T", "sub": "コンピュータ", "term": "マルチコアプロセッサ", "desc": "1つのCPUの中に、処理を行う中心部分（コア）を複数持つもの。複数の処理を同時に進められる。"}, {"id": "0417", "f": "T", "sub": "コンピュータ", "term": "GPU", "desc": "画像を描く処理を得意とするプロセッサ。大量の計算を同時に行えるので、AIの学習にも使われる。", "abbr": "Graphics Processing Unit"}, {"id": "0418", "f": "T", "sub": "コンピュータ", "term": "主記憶装置（メインメモリ）", "desc": "CPUが直接読み書きする記憶装置。実行中のプログラムやデータを一時的に置く。"}, {"id": "0419", "f": "T", "sub": "コンピュータ", "term": "キャッシュメモリ", "desc": "CPUとメインメモリの間に置く、小さくて高速なメモリ。よく使うデータを置いて、処理を速くする。"}, {"id": "0420", "f": "T", "sub": "コンピュータ", "term": "RAM", "desc": "読み書きができるメモリ。電源を切ると内容が消える（揮発性）。", "abbr": "Random Access Memory"}, {"id": "0421", "f": "T", "sub": "コンピュータ", "term": "ROM", "desc": "読み出し専用のメモリ。電源を切っても内容が消えない（不揮発性）。", "abbr": "Read Only Memory"}, {"id": "0422", "f": "T", "sub": "コンピュータ", "term": "DRAM", "desc": "メインメモリに使われるRAM。安くて容量を大きくしやすいが、内容を保つために定期的な書き直し（リフレッシュ）が必要。", "abbr": "Dynamic Random Access Memory"}, {"id": "0423", "f": "T", "sub": "コンピュータ", "term": "SRAM", "desc": "キャッシュメモリに使われるRAM。高速だが値段が高い。リフレッシュは要らない。", "abbr": "Static Random Access Memory"}, {"id": "0424", "f": "T", "sub": "コンピュータ", "term": "フラッシュメモリ", "desc": "電源を切っても内容が消えず、電気的に書き換えができるメモリ。USBメモリやSSDに使われる。"}, {"id": "0425", "f": "T", "sub": "コンピュータ", "term": "補助記憶装置", "desc": "電源を切ってもデータを保存しておける記憶装置。SSD・HDD・USBメモリなど。"}, {"id": "0426", "f": "T", "sub": "コンピュータ", "term": "SSD", "desc": "フラッシュメモリを使った補助記憶装置。HDDより高速で、衝撃に強く、音もしない。", "abbr": "Solid State Drive"}, {"id": "0427", "f": "T", "sub": "コンピュータ", "term": "HDD", "desc": "磁気ディスクを回転させてデータを読み書きする補助記憶装置。容量あたりの値段が安い。", "abbr": "Hard Disk Drive"}, {"id": "0428", "f": "T", "sub": "コンピュータ", "term": "SDメモリカード", "desc": "フラッシュメモリを使った小型のメモリカード。デジタルカメラやスマートフォンなどで使う。"}, {"id": "0429", "f": "T", "sub": "コンピュータ", "term": "USB", "desc": "パソコンと周辺機器をつなぐための規格。USB Type-Cなどの形がある。", "abbr": "Universal Serial Bus"}, {"id": "0430", "f": "T", "sub": "コンピュータ", "term": "Bluetooth", "desc": "数メートルから数十メートルの近い距離で、機器どうしを無線でつなぐ規格。イヤホンやマウスなどで使う。"}, {"id": "0431", "f": "T", "sub": "コンピュータ", "term": "NFC", "desc": "10cm程度のごく近い距離で、機器をかざして無線通信を行う規格。交通系ICカードやスマートフォンでの支払いに使う。", "abbr": "Near Field Communication"}, {"id": "0432", "f": "T", "sub": "コンピュータ", "term": "HDMI", "desc": "映像と音声を、1本のケーブルでまとめて送るための規格。テレビやディスプレイの接続に使う。", "abbr": "High-Definition Multimedia Interface"}, {"id": "0433", "f": "T", "sub": "コンピュータ", "term": "デバイスドライバ", "desc": "周辺機器をOSから動かすためのソフトウェア。"}, {"id": "0434", "f": "T", "sub": "コンピュータ", "term": "プラグアンドプレイ", "desc": "周辺機器をパソコンにつなぐだけで、必要な設定が自動で行われて、使えるようになる仕組み。"}, {"id": "0435", "f": "T", "sub": "コンピュータ", "term": "ホットプラグ", "desc": "パソコンの電源を入れたまま、周辺機器を抜き差しできる仕組み。"}, {"id": "0436", "f": "T", "sub": "コンピュータ", "term": "解像度", "desc": "画像やディスプレイを構成する点（画素）の細かさ。数が多いほど細かく表示できる。"}, {"id": "0437", "f": "T", "sub": "コンピュータ", "term": "タッチパネル", "desc": "画面に指などで触れて操作する入力装置。"}, {"id": "0438", "f": "T", "sub": "コンピュータ", "term": "3Dプリンタ", "desc": "立体のデータをもとに、樹脂などを積み重ねて立体物を作る装置。"}, {"id": "0439", "f": "T", "sub": "コンピュータ", "term": "IoT", "desc": "モノのインターネットのこと。家電や車などのさまざまなモノがインターネットにつながり、情報をやり取りする仕組み。", "abbr": "Internet of Things"}, {"id": "0440", "f": "T", "sub": "コンピュータ", "term": "センサ", "desc": "温度・光・音・動きなどを測り、電気の信号に変える部品。"}, {"id": "0441", "f": "T", "sub": "コンピュータ", "term": "アクチュエータ", "desc": "電気の信号を受けて、物を動かしたり回したりする部品。モータなど。"}, {"id": "0442", "f": "T", "sub": "コンピュータ", "term": "ウェアラブル端末", "desc": "腕時計やめがねのように、身に付けて使うコンピュータ。"}, {"id": "0443", "f": "T", "sub": "システム構成", "term": "クライアントサーバシステム", "desc": "サービスを頼む側（クライアント）と、サービスを提供する側（サーバ）に役割を分けて処理するシステムの形。"}, {"id": "0444", "f": "T", "sub": "システム構成", "term": "ピアツーピア（P2P）", "desc": "サーバを置かずに、つながっている機器どうしが対等な立場でデータをやり取りする形。"}, {"id": "0445", "f": "T", "sub": "システム構成", "term": "シンクライアント", "desc": "利用者の端末には最低限の機能だけを持たせ、アプリケーションやデータはサーバで管理する仕組み。"}, {"id": "0446", "f": "T", "sub": "システム構成", "term": "仮想化", "desc": "1台のコンピュータの上で、複数の仮想的なコンピュータを動かす技術。"}, {"id": "0447", "f": "T", "sub": "システム構成", "term": "エッジコンピューティング", "desc": "データを遠くのクラウドに送らずに、利用者や機器の近く（エッジ）で処理する考え方。通信の遅れや量を減らせる。"}, {"id": "0448", "f": "T", "sub": "システム構成", "term": "バッチ処理", "desc": "データを一定の期間や量でまとめておき、一度に処理する方式。"}, {"id": "0449", "f": "T", "sub": "システム構成", "term": "リアルタイム処理", "desc": "データが発生したら、すぐに処理する方式。"}, {"id": "0450", "f": "T", "sub": "システム構成", "term": "デュアルシステム", "desc": "2つのシステムで同じ処理を同時に行い、結果を照らし合わせるシステム。一方が故障しても処理を続けられる。"}, {"id": "0451", "f": "T", "sub": "システム構成", "term": "デュプレックスシステム", "desc": "本番で使うシステムと予備のシステムを用意しておき、故障したら予備に切り替えるシステム。"}, {"id": "0452", "f": "T", "sub": "システム構成", "term": "RAID", "desc": "複数のHDDやSSDを組み合わせて、1台の装置のように使う技術。速さや信頼性を高める。", "abbr": "Redundant Arrays of Independent Disks"}, {"id": "0453", "f": "T", "sub": "システム構成", "term": "ストライピング（RAID0）", "desc": "データを複数のディスクに分けて書き込み、読み書きを速くする方法。信頼性は上がらない。"}, {"id": "0454", "f": "T", "sub": "システム構成", "term": "ミラーリング（RAID1）", "desc": "同じデータを2台以上のディスクに書き込み、1台が壊れてもデータを失わないようにする方法。"}, {"id": "0455", "f": "T", "sub": "システム構成", "term": "RAID5", "desc": "データと、誤りを直すためのパリティを、複数のディスクに分散して書き込む方法。1台が壊れても、データを元に戻せる。"}, {"id": "0456", "f": "T", "sub": "システム構成", "term": "NAS", "desc": "ネットワークに直接つないで、複数のコンピュータからファイルを共有できる記憶装置。", "abbr": "Network Attached Storage"}, {"id": "0457", "f": "T", "sub": "システム構成", "term": "稼働率", "desc": "システムが正常に動いている時間の割合。MTBF ÷（MTBF + MTTR）で求める。"}, {"id": "0458", "f": "T", "sub": "システム構成", "term": "MTBF", "desc": "平均故障間隔のこと。故障が直ってから次に故障するまでの、正常に動いている時間の平均。", "abbr": "Mean Time Between Failures"}, {"id": "0459", "f": "T", "sub": "システム構成", "term": "MTTR", "desc": "平均修復時間のこと。故障してから直るまでにかかる時間の平均。", "abbr": "Mean Time To Repair"}, {"id": "0460", "f": "T", "sub": "システム構成", "term": "フォールトトレランス", "desc": "故障が起きても、システム全体の機能を止めずに動かし続けられるようにする考え方。"}, {"id": "0461", "f": "T", "sub": "システム構成", "term": "フェールセーフ", "desc": "故障が起きたときに、安全な側に動作させて被害を防ぐ考え方。例: 故障したら信号機を赤にする。"}, {"id": "0462", "f": "T", "sub": "システム構成", "term": "フェールソフト", "desc": "故障が起きたときに、故障した部分を切り離し、機能を落としてでもシステムを動かし続ける考え方。"}, {"id": "0463", "f": "T", "sub": "システム構成", "term": "フールプルーフ", "desc": "利用者が間違った操作をしても、誤動作しないように作っておく考え方。"}, {"id": "0464", "f": "T", "sub": "システム構成", "term": "レスポンスタイム", "desc": "システムに処理を頼んでから、最初の応答が返ってくるまでの時間。"}, {"id": "0465", "f": "T", "sub": "システム構成", "term": "スループット", "desc": "一定の時間に処理できる仕事の量。"}, {"id": "0466", "f": "T", "sub": "システム構成", "term": "ベンチマーク", "desc": "決まった処理を実行させて、システムの性能を測り、比べること。"}, {"id": "0467", "f": "T", "sub": "システム構成", "term": "スケールアウト", "desc": "サーバの台数を増やして、システム全体の処理能力を高めること。"}, {"id": "0468", "f": "T", "sub": "システム構成", "term": "スケールアップ", "desc": "サーバの部品をより高性能なものに替えて、1台あたりの処理能力を高めること。"}, {"id": "0469", "f": "T", "sub": "システム構成", "term": "TCO", "desc": "総所有費用のこと。システムの導入費用だけでなく、運用や保守、教育などにかかる費用も含めた総額。", "abbr": "Total Cost of Ownership"}, {"id": "0470", "f": "T", "sub": "ソフトウェア", "term": "OS", "desc": "オペレーティングシステムのこと。コンピュータ全体を管理し、アプリケーションが動くための基盤となる基本ソフトウェア。Windows・macOS・Linux・Android・iOSなど。", "abbr": "Operating System"}, {"id": "0471", "f": "T", "sub": "ソフトウェア", "term": "アプリケーションソフトウェア", "desc": "文書作成や表計算など、利用者の目的に合わせた仕事をするソフトウェア。"}, {"id": "0472", "f": "T", "sub": "ソフトウェア", "term": "ミドルウェア", "desc": "OSとアプリケーションの間で、データベースの管理など、多くのアプリケーションに共通する機能を提供するソフトウェア。"}, {"id": "0473", "f": "T", "sub": "ソフトウェア", "term": "ファームウェア", "desc": "機器の中のROMやフラッシュメモリに書き込まれ、ハードウェアを制御するソフトウェア。"}, {"id": "0474", "f": "T", "sub": "ソフトウェア", "term": "マルチタスク", "desc": "1台のコンピュータで、複数の処理（タスク）を切り替えながら、同時に進めているように動かすこと。"}, {"id": "0475", "f": "T", "sub": "ソフトウェア", "term": "仮想記憶", "desc": "補助記憶装置の一部を使って、実際のメインメモリより大きな記憶領域があるように見せる仕組み。"}, {"id": "0476", "f": "T", "sub": "ソフトウェア", "term": "ディレクトリ", "desc": "ファイルをまとめて整理するための入れ物。フォルダとも呼ぶ。階層の構造で管理する。"}, {"id": "0477", "f": "T", "sub": "ソフトウェア", "term": "絶対パス", "desc": "一番上の階層（ルートディレクトリ）から、目的のファイルまでの道筋をすべて書いたもの。"}, {"id": "0478", "f": "T", "sub": "ソフトウェア", "term": "相対パス", "desc": "今いるディレクトリ（カレントディレクトリ）を基準にして、目的のファイルまでの道筋を書いたもの。"}, {"id": "0479", "f": "T", "sub": "ソフトウェア", "term": "拡張子", "desc": "ファイル名の最後の「.」の後ろに付く文字。ファイルの種類を表す（例: .jpg .pdf）。"}, {"id": "0480", "f": "T", "sub": "ソフトウェア", "term": "バックアップ", "desc": "データが壊れたり消えたりしたときに備えて、別の場所に写しを取っておくこと。"}, {"id": "0481", "f": "T", "sub": "ソフトウェア", "term": "フルバックアップ", "desc": "すべてのデータを、丸ごと写し取るバックアップ。"}, {"id": "0482", "f": "T", "sub": "ソフトウェア", "term": "差分バックアップ", "desc": "最後のフルバックアップの後に変わったデータだけを、写し取るバックアップ。"}, {"id": "0483", "f": "T", "sub": "ソフトウェア", "term": "増分バックアップ", "desc": "前回のバックアップ（フルでも増分でも）の後に変わったデータだけを、写し取るバックアップ。"}, {"id": "0484", "f": "T", "sub": "ソフトウェア", "term": "表計算ソフト", "desc": "表の形でデータを入力し、計算・集計・グラフの作成ができるソフトウェア。"}, {"id": "0485", "f": "T", "sub": "ソフトウェア", "term": "相対参照", "desc": "表計算ソフトで、式を他のセルに写したときに、参照するセルの位置も一緒にずれる参照の仕方。"}, {"id": "0486", "f": "T", "sub": "ソフトウェア", "term": "絶対参照", "desc": "表計算ソフトで、式を他のセルに写しても、参照するセルの位置が変わらない参照の仕方。「$」を付けて表す。"}, {"id": "0487", "f": "T", "sub": "ソフトウェア", "term": "OSS", "desc": "オープンソースソフトウェアのこと。ソースコードが公開され、決められた条件のもとで、誰でも使用・改変・再配布できるソフトウェア。", "abbr": "Open Source Software"}, {"id": "0488", "f": "T", "sub": "ソフトウェア", "term": "Linux", "desc": "代表的なOSSのOS。サーバなどで広く使われている。"}, {"id": "0489", "f": "T", "sub": "ソフトウェア", "term": "コピーレフト", "desc": "著作権を持ったまま、改変したものも同じ条件で公開することを求める考え方。GPLなどのライセンスで使われる。"}, {"id": "0490", "f": "T", "sub": "ソフトウェア", "term": "API", "desc": "ソフトウェアの機能やデータを、外部の別のプログラムから呼び出して使うための窓口（取決め）。", "abbr": "Application Programming Interface"}, {"id": "0491", "f": "T", "sub": "ソフトウェア", "term": "Webブラウザ", "desc": "Webページを見るためのソフトウェア。"}, {"id": "0492", "f": "T", "sub": "ソフトウェア", "term": "Cookie", "desc": "Webサイトが利用者のブラウザに保存させる、小さなデータ。ログインの状態などを覚えておくために使う。クッキーとも書く。"}, {"id": "0493", "f": "T", "sub": "画面と情報メディア", "term": "GUI", "desc": "アイコンやボタンなどを画面に表示し、マウスや指で操作できるようにした画面の仕組み。", "abbr": "Graphical User Interface"}, {"id": "0494", "f": "T", "sub": "画面と情報メディア", "term": "CUI", "desc": "キーボードで文字のコマンドを入力して操作する画面の仕組み。", "abbr": "Character User Interface"}, {"id": "0495", "f": "T", "sub": "画面と情報メディア", "term": "ユーザビリティ", "desc": "利用者が目的を効率よく、満足して達成できるかという、使いやすさの度合い。"}, {"id": "0496", "f": "T", "sub": "画面と情報メディア", "term": "アクセシビリティ", "desc": "高齢者や障害のある人などを含め、誰でも同じように情報やサービスを利用できること。"}, {"id": "0497", "f": "T", "sub": "画面と情報メディア", "term": "ユニバーサルデザイン", "desc": "年齢や障害の有無などに関係なく、できるだけ多くの人が使いやすいように、最初から設計すること。"}, {"id": "0498", "f": "T", "sub": "画面と情報メディア", "term": "UX", "desc": "ユーザエクスペリエンスのこと。製品やサービスを使ったときに、利用者が得られる体験の全体。", "abbr": "User Experience"}, {"id": "0499", "f": "T", "sub": "画面と情報メディア", "term": "レスポンシブデザイン", "desc": "パソコン・タブレット・スマートフォンなど、画面の大きさに合わせて、Webページの表示が自動で変わるようにする作り方。"}, {"id": "0500", "f": "T", "sub": "画面と情報メディア", "term": "ラジオボタン", "desc": "複数の選択肢の中から、1つだけを選ぶ画面の部品。"}, {"id": "0501", "f": "T", "sub": "画面と情報メディア", "term": "チェックボックス", "desc": "複数の選択肢の中から、当てはまるものをいくつでも選べる画面の部品。"}, {"id": "0502", "f": "T", "sub": "画面と情報メディア", "term": "プルダウンメニュー", "desc": "クリックすると選択肢の一覧が下に開き、その中から選ぶ画面の部品。"}, {"id": "0503", "f": "T", "sub": "画面と情報メディア", "term": "ピクトグラム", "desc": "トイレや非常口など、伝えたい情報を、言葉を使わずに分かりやすい絵で表した記号。"}, {"id": "0504", "f": "T", "sub": "画面と情報メディア", "term": "JPEG", "desc": "写真などのカラーの静止画を圧縮して保存するための形式。圧縮すると画質が少し落ちる（非可逆圧縮）。", "abbr": "Joint Photographic Experts Group"}, {"id": "0505", "f": "T", "sub": "画面と情報メディア", "term": "PNG", "desc": "画質を落とさずに圧縮できる静止画の形式。透明な部分も表現できる。", "abbr": "Portable Network Graphics"}, {"id": "0506", "f": "T", "sub": "画面と情報メディア", "term": "GIF", "desc": "256色までの静止画の形式。簡単なアニメーションも表現できる。", "abbr": "Graphics Interchange Format"}, {"id": "0507", "f": "T", "sub": "画面と情報メディア", "term": "MPEG", "desc": "動画を圧縮して保存するための形式。", "abbr": "Moving Picture Experts Group"}, {"id": "0508", "f": "T", "sub": "画面と情報メディア", "term": "MP3", "desc": "音声を圧縮して保存するための形式。", "abbr": "MPEG-1 Audio Layer-3"}, {"id": "0509", "f": "T", "sub": "画面と情報メディア", "term": "PDF", "desc": "パソコンの機種や環境に関係なく、同じ見た目で文書を表示・印刷できるファイルの形式。", "abbr": "Portable Document Format"}, {"id": "0510", "f": "T", "sub": "画面と情報メディア", "term": "CSV", "desc": "データを「,」（カンマ）で区切って並べたテキストの形式。表計算ソフトとのデータのやり取りによく使う。", "abbr": "Comma Separated Values"}, {"id": "0511", "f": "T", "sub": "画面と情報メディア", "term": "可逆圧縮", "desc": "圧縮したデータを元に戻したときに、完全に元どおりになる圧縮方式。"}, {"id": "0512", "f": "T", "sub": "画面と情報メディア", "term": "非可逆圧縮", "desc": "圧縮したデータを元に戻しても、完全には元どおりにならない圧縮方式。そのかわり、ファイルを小さくできる。"}, {"id": "0513", "f": "T", "sub": "画面と情報メディア", "term": "RGB", "desc": "光の三原色である赤（Red）・緑（Green）・青（Blue）。ディスプレイは、この3色を混ぜて色を表す。"}, {"id": "0514", "f": "T", "sub": "画面と情報メディア", "term": "CG（コンピュータグラフィックス）", "desc": "コンピュータを使って画像や映像を作る技術。"}, {"id": "0515", "f": "T", "sub": "画面と情報メディア", "term": "AR", "desc": "拡張現実のこと。現実の風景に、コンピュータで作った情報や映像を重ねて表示する技術。", "abbr": "Augmented Reality"}, {"id": "0516", "f": "T", "sub": "画面と情報メディア", "term": "VR", "desc": "仮想現実のこと。コンピュータで作った仮想の世界を、実際にその場にいるように体験できる技術。", "abbr": "Virtual Reality"}, {"id": "0517", "f": "T", "sub": "画面と情報メディア", "term": "メタバース", "desc": "インターネット上に作られた3次元の仮想空間。アバター（分身）を通して、他の人と交流したり、サービスを受けたりする。"}, {"id": "0518", "f": "T", "sub": "データベース", "term": "データベース", "desc": "たくさんのデータを整理して蓄え、検索や更新をしやすくしたもの。"}, {"id": "0519", "f": "T", "sub": "データベース", "term": "関係データベース", "desc": "データを、行と列からなる表（テーブル）の形で管理するデータベース。リレーショナルデータベースとも呼ぶ。"}, {"id": "0520", "f": "T", "sub": "データベース", "term": "DBMS", "desc": "データベース管理システムのこと。データベースを作り、データの追加・検索・更新などを管理するソフトウェア。", "abbr": "Database Management System"}, {"id": "0521", "f": "T", "sub": "データベース", "term": "SQL", "desc": "関係データベースのデータを操作するための言語。"}, {"id": "0522", "f": "T", "sub": "データベース", "term": "レコード", "desc": "表の1行分のデータ。行とも呼ぶ。"}, {"id": "0523", "f": "T", "sub": "データベース", "term": "フィールド", "desc": "表の1列分の項目。列とも呼ぶ。"}, {"id": "0524", "f": "T", "sub": "データベース", "term": "主キー", "desc": "表の中で、1つの行を特定するための項目（列）。同じ値や空の値は入れられない。"}, {"id": "0525", "f": "T", "sub": "データベース", "term": "外部キー", "desc": "他の表の主キーを参照する項目。表どうしの関係を表す。"}, {"id": "0526", "f": "T", "sub": "データベース", "term": "正規化", "desc": "データの重複をなくすように表を分けて、データの矛盾が起きにくくすること。"}, {"id": "0527", "f": "T", "sub": "データベース", "term": "E-R図", "desc": "データベースを設計するときに、実体（エンティティ）とその関係（リレーションシップ）を図で表したもの。"}, {"id": "0528", "f": "T", "sub": "データベース", "term": "選択", "desc": "表から、条件に合う行だけを取り出す操作。"}, {"id": "0529", "f": "T", "sub": "データベース", "term": "射影", "desc": "表から、指定した列だけを取り出す操作。"}, {"id": "0530", "f": "T", "sub": "データベース", "term": "結合", "desc": "2つ以上の表を、共通する項目でつないで1つの表にする操作。"}, {"id": "0531", "f": "T", "sub": "データベース", "term": "インデックス", "desc": "データを速く探すために作る索引。"}, {"id": "0532", "f": "T", "sub": "データベース", "term": "トランザクション", "desc": "データベースに対する、分けることのできない一連の処理のまとまり。すべて成功するか、すべて取り消すかのどちらかにする。"}, {"id": "0533", "f": "T", "sub": "データベース", "term": "排他制御", "desc": "複数の利用者が同じデータを同時に更新して矛盾が起きないように、他の利用者の更新を一時的に止める仕組み。"}, {"id": "0534", "f": "T", "sub": "データベース", "term": "ロック", "desc": "排他制御のために、データを使っている間、他の処理がそのデータを更新できないようにすること。"}, {"id": "0535", "f": "T", "sub": "データベース", "term": "デッドロック", "desc": "複数の処理が、お互いに相手が使っているデータの解放を待ち続け、どちらも先に進めなくなる状態。"}, {"id": "0536", "f": "T", "sub": "データベース", "term": "コミット", "desc": "トランザクションの処理がすべて成功したときに、データベースの更新を確定させること。"}, {"id": "0537", "f": "T", "sub": "データベース", "term": "ロールバック", "desc": "トランザクションの途中で障害が起きたときに、処理を取り消して、始まる前の状態に戻すこと。"}, {"id": "0538", "f": "T", "sub": "データベース", "term": "ロールフォワード", "desc": "障害が起きたときに、バックアップのデータに更新の記録（ログ）を使って更新を反映し、障害の直前の状態まで戻すこと。"}, {"id": "0539", "f": "T", "sub": "データベース", "term": "データウェアハウス", "desc": "企業の中のさまざまなシステムのデータを、分析しやすい形で時系列に集めて蓄えたもの。"}, {"id": "0540", "f": "T", "sub": "データベース", "term": "データレイク", "desc": "さまざまな形式のデータを、加工せずにそのままの形でまとめて蓄えておく場所。"}, {"id": "0541", "f": "T", "sub": "データベース", "term": "NoSQL", "desc": "表の形にこだわらず、大量のデータを高速に扱えるようにしたデータベースの総称。キーバリュー型などがある。"}, {"id": "0542", "f": "T", "sub": "ネットワーク", "term": "LAN", "desc": "会社や家庭の中など、限られた範囲で使うネットワーク。", "abbr": "Local Area Network"}, {"id": "0543", "f": "T", "sub": "ネットワーク", "term": "WAN", "desc": "離れた場所のLANどうしなどを、通信事業者の回線を使ってつなぐ、広い範囲のネットワーク。", "abbr": "Wide Area Network"}, {"id": "0544", "f": "T", "sub": "ネットワーク", "term": "無線LAN", "desc": "ケーブルを使わずに、電波でつなぐLAN。IEEE 802.11という規格で決められている。"}, {"id": "0545", "f": "T", "sub": "ネットワーク", "term": "Wi-Fi", "desc": "無線LANの規格に対応した機器どうしが、互いにつながることを認められていることを示すブランド名。一般に、無線LANと同じ意味で使われる。"}, {"id": "0546", "f": "T", "sub": "ネットワーク", "term": "アクセスポイント", "desc": "無線LANの電波を出し、パソコンやスマートフォンをネットワークにつなぐ機器。"}, {"id": "0547", "f": "T", "sub": "ネットワーク", "term": "SSID", "desc": "無線LANのアクセスポイントを見分けるための名前。", "abbr": "Service Set Identifier"}, {"id": "0548", "f": "T", "sub": "ネットワーク", "term": "WPA3", "desc": "無線LANの通信を暗号化するためのセキュリティの規格。WPA2の後継。", "abbr": "Wi-Fi Protected Access 3"}, {"id": "0549", "f": "T", "sub": "ネットワーク", "term": "テザリング", "desc": "スマートフォンをアクセスポイントのように使い、パソコンなどをインターネットにつなぐこと。"}, {"id": "0550", "f": "T", "sub": "ネットワーク", "term": "ルータ", "desc": "異なるネットワークどうしをつなぎ、データを目的の場所へ届けるための道筋を選ぶ機器。"}, {"id": "0551", "f": "T", "sub": "ネットワーク", "term": "スイッチングハブ", "desc": "複数の機器をつなぐ集線装置のうち、データを、送り先の機器がつながる口（ポート）にだけ送るもの。"}, {"id": "0552", "f": "T", "sub": "ネットワーク", "term": "プロトコル", "desc": "コンピュータどうしが通信するときの決まりごと（手順や形式）。"}, {"id": "0553", "f": "T", "sub": "ネットワーク", "term": "TCP/IP", "desc": "インターネットで使われている、標準的な通信プロトコルの集まり。"}, {"id": "0554", "f": "T", "sub": "ネットワーク", "term": "パケット", "desc": "通信で送るデータを、小さく分けたまとまり。"}, {"id": "0555", "f": "T", "sub": "ネットワーク", "term": "bps", "desc": "通信の速さの単位。1秒間に送れるビットの数を表す。", "abbr": "bits per second"}, {"id": "0556", "f": "T", "sub": "ネットワーク", "term": "IPアドレス", "desc": "ネットワークにつながる機器を見分けるための番号。インターネットの住所のようなもの。"}, {"id": "0557", "f": "T", "sub": "ネットワーク", "term": "IPv4", "desc": "IPアドレスを32ビットで表す方式。使えるアドレスの数が足りなくなってきている。"}, {"id": "0558", "f": "T", "sub": "ネットワーク", "term": "IPv6", "desc": "IPアドレスを128ビットで表す方式。IPv4よりはるかに多くのアドレスを使える。"}, {"id": "0559", "f": "T", "sub": "ネットワーク", "term": "グローバルIPアドレス", "desc": "インターネット上で重ならないように割り当てられるIPアドレス。"}, {"id": "0560", "f": "T", "sub": "ネットワーク", "term": "プライベートIPアドレス", "desc": "会社や家庭のLANの中で自由に使えるIPアドレス。そのままではインターネットと通信できない。"}, {"id": "0561", "f": "T", "sub": "ネットワーク", "term": "NAT", "desc": "プライベートIPアドレスとグローバルIPアドレスを変換して、LANの中の機器がインターネットを使えるようにする仕組み。", "abbr": "Network Address Translation"}, {"id": "0562", "f": "T", "sub": "ネットワーク", "term": "DHCP", "desc": "ネットワークにつないだ機器に、IPアドレスなどの設定を自動で割り当てるプロトコル。", "abbr": "Dynamic Host Configuration Protocol"}, {"id": "0563", "f": "T", "sub": "ネットワーク", "term": "DNS", "desc": "「www.example.jp」のようなドメイン名と、IPアドレスを対応付ける仕組み。", "abbr": "Domain Name System"}, {"id": "0564", "f": "T", "sub": "ネットワーク", "term": "ドメイン名", "desc": "IPアドレスの代わりに、人が覚えやすいように付けたネットワーク上の名前（例: example.jp）。"}, {"id": "0565", "f": "T", "sub": "ネットワーク", "term": "URL", "desc": "インターネット上のWebページなどの場所を示す書き方（例: https://www.example.jp/index.html）。", "abbr": "Uniform Resource Locator"}, {"id": "0566", "f": "T", "sub": "ネットワーク", "term": "MACアドレス", "desc": "ネットワークにつなぐ機器（の通信部品）ごとに、製造のときに割り当てられる番号。"}, {"id": "0567", "f": "T", "sub": "ネットワーク", "term": "ポート番号", "desc": "1台のコンピュータの中で、通信の相手となるアプリケーションを見分けるための番号。"}, {"id": "0568", "f": "T", "sub": "ネットワーク", "term": "HTTP", "desc": "WebブラウザとWebサーバの間で、Webページのデータをやり取りするためのプロトコル。", "abbr": "HyperText Transfer Protocol"}, {"id": "0569", "f": "T", "sub": "ネットワーク", "term": "HTTPS", "desc": "HTTPの通信を、TLSで暗号化したもの。", "abbr": "HyperText Transfer Protocol Secure"}, {"id": "0570", "f": "T", "sub": "ネットワーク", "term": "SMTP", "desc": "電子メールを送信したり、メールサーバの間で転送したりするためのプロトコル。", "abbr": "Simple Mail Transfer Protocol"}, {"id": "0571", "f": "T", "sub": "ネットワーク", "term": "POP3", "desc": "メールサーバから、メールを自分の端末に受信するためのプロトコル。受け取ったメールは端末に保存される。", "abbr": "Post Office Protocol version 3"}, {"id": "0572", "f": "T", "sub": "ネットワーク", "term": "IMAP", "desc": "メールをサーバに置いたまま、読んだり管理したりするためのプロトコル。複数の端末で同じメールを見られる。", "abbr": "Internet Message Access Protocol"}, {"id": "0573", "f": "T", "sub": "ネットワーク", "term": "FTP", "desc": "ネットワークで、ファイルを送ったり受け取ったりするためのプロトコル。", "abbr": "File Transfer Protocol"}, {"id": "0574", "f": "T", "sub": "ネットワーク", "term": "NTP", "desc": "ネットワークにつながる機器の時刻を、正しい時刻に合わせるためのプロトコル。", "abbr": "Network Time Protocol"}, {"id": "0575", "f": "T", "sub": "ネットワーク", "term": "MIME", "desc": "電子メールで、画像などの文字以外のデータや、日本語などを送れるようにする仕組み。", "abbr": "Multipurpose Internet Mail Extensions"}, {"id": "0576", "f": "T", "sub": "ネットワーク", "term": "CC", "desc": "電子メールで、本来の宛先以外の人にも同じメールを送るときに使う欄。受け取った人全員に、そのアドレスが見える。", "abbr": "Carbon Copy"}, {"id": "0577", "f": "T", "sub": "ネットワーク", "term": "BCC", "desc": "電子メールで、他の受信者にアドレスを知られずに、同じメールを送るときに使う欄。", "abbr": "Blind Carbon Copy"}, {"id": "0578", "f": "T", "sub": "ネットワーク", "term": "VPN", "desc": "インターネットなどの公共のネットワークの上に、暗号化などで仮想的な専用のネットワークを作る技術。", "abbr": "Virtual Private Network"}, {"id": "0579", "f": "T", "sub": "ネットワーク", "term": "5G", "desc": "第5世代の移動通信システム。高速・大容量、遅れが小さい、多くの機器を同時につなげるのが特徴。"}, {"id": "0580", "f": "T", "sub": "ネットワーク", "term": "LPWA", "desc": "少ない電力で、広い範囲の通信ができる無線通信の技術の総称。IoTで使われる。", "abbr": "Low Power Wide Area"}, {"id": "0581", "f": "T", "sub": "ネットワーク", "term": "SIMカード", "desc": "携帯電話の契約者を識別する情報が記録されたICカード。本体に組み込まれたものはeSIMと呼ぶ。"}, {"id": "0582", "f": "T", "sub": "ネットワーク", "term": "MVNO", "desc": "自分では通信回線の設備を持たず、他の通信事業者から借りて通信サービスを提供する事業者。格安SIMなど。", "abbr": "Mobile Virtual Network Operator"}, {"id": "0583", "f": "T", "sub": "ネットワーク", "term": "ローミング", "desc": "契約している通信事業者のサービスエリアの外でも、提携先の事業者の設備を使って通信できるようにすること。"}, {"id": "0584", "f": "T", "sub": "ネットワーク", "term": "ビーコン", "desc": "電波などを定期的に出して、位置などの情報を伝える装置。Bluetoothを使ったものが店舗などで使われる。"}, {"id": "0585", "f": "T", "sub": "セキュリティ", "term": "情報セキュリティの3要素", "desc": "機密性・完全性・可用性のこと。情報を安全に守るために、維持すべき3つの性質。"}, {"id": "0586", "f": "T", "sub": "セキュリティ", "term": "機密性", "desc": "許可された人だけが、情報を使える状態にすること。"}, {"id": "0587", "f": "T", "sub": "セキュリティ", "term": "完全性", "desc": "情報が正確で、改ざんされたり壊れたりしていない状態にすること。"}, {"id": "0588", "f": "T", "sub": "セキュリティ", "term": "可用性", "desc": "必要なときに、いつでも情報やシステムを使える状態にすること。"}, {"id": "0589", "f": "T", "sub": "セキュリティ", "term": "情報資産", "desc": "データ・書類・ソフトウェア・機器など、組織にとって価値があり、守るべき情報や関連するもの。"}, {"id": "0590", "f": "T", "sub": "セキュリティ", "term": "脅威", "desc": "情報資産に損害を与えるおそれのある原因。不正アクセス・災害・操作のミスなど。"}, {"id": "0591", "f": "T", "sub": "セキュリティ", "term": "脆弱性", "desc": "脅威に付け込まれる弱点。ソフトウェアの不具合（セキュリティホール）や、管理の不備など。"}, {"id": "0592", "f": "T", "sub": "セキュリティ", "term": "リスクアセスメント", "desc": "リスクを洗い出し（特定）、その大きさを分析し、対策が必要かどうかを評価する一連の流れ。"}, {"id": "0593", "f": "T", "sub": "セキュリティ", "term": "リスク回避", "desc": "リスクの原因となる活動そのものをやめて、リスクをなくすこと。"}, {"id": "0594", "f": "T", "sub": "セキュリティ", "term": "リスク低減", "desc": "対策をとって、リスクが起きる可能性や、起きたときの影響を小さくすること。"}, {"id": "0595", "f": "T", "sub": "セキュリティ", "term": "リスク移転", "desc": "保険をかけたり外部に業務を任せたりして、リスクを他者と分け合うこと。リスク共有とも呼ぶ。"}, {"id": "0596", "f": "T", "sub": "セキュリティ", "term": "リスク受容", "desc": "リスクが小さい場合などに、特に対策をとらず、そのまま受け入れること。リスク保有とも呼ぶ。"}, {"id": "0597", "f": "T", "sub": "セキュリティ", "term": "ISMS", "desc": "情報セキュリティマネジメントシステムのこと。組織が情報セキュリティを継続して管理・改善するための仕組み。", "abbr": "Information Security Management System"}, {"id": "0598", "f": "T", "sub": "セキュリティ", "term": "情報セキュリティポリシー", "desc": "組織が情報セキュリティにどう取り組むかの方針や、守るべきルールを文書にしたもの。"}, {"id": "0599", "f": "T", "sub": "セキュリティ", "term": "CSIRT", "desc": "セキュリティの事故（インシデント）が起きたときに、対応にあたる組織の中のチーム。", "abbr": "Computer Security Incident Response Team"}, {"id": "0600", "f": "T", "sub": "セキュリティ", "term": "SOC", "desc": "ネットワークや機器を24時間監視し、サイバー攻撃を見つけて分析する組織。", "abbr": "Security Operation Center"}, {"id": "0601", "f": "T", "sub": "セキュリティ", "term": "不正のトライアングル", "desc": "不正は「機会」「動機」「正当化」の3つがそろうと起きやすくなるという考え方。"}, {"id": "0602", "f": "T", "sub": "セキュリティ", "term": "マルウェア", "desc": "利用者の端末に害を与える、悪意のあるソフトウェアの総称。ウイルス・ワーム・ランサムウェアなど。"}, {"id": "0603", "f": "T", "sub": "セキュリティ", "term": "コンピュータウイルス", "desc": "他のプログラムに入り込んで増え、データを壊すなどの害を与える、悪意のあるプログラム。"}, {"id": "0604", "f": "T", "sub": "セキュリティ", "term": "ワーム", "desc": "他のプログラムに頼らず、自分自身を複製して、ネットワークを通じて広がっていくマルウェア。"}, {"id": "0605", "f": "T", "sub": "セキュリティ", "term": "トロイの木馬", "desc": "役に立つプログラムのふりをして入り込み、裏で悪いことをするマルウェア。"}, {"id": "0606", "f": "T", "sub": "セキュリティ", "term": "スパイウェア", "desc": "利用者に気付かれないように、端末の中の情報を集めて外部に送るマルウェア。"}, {"id": "0607", "f": "T", "sub": "セキュリティ", "term": "ランサムウェア", "desc": "データを暗号化するなどして使えなくし、元に戻すことと引き換えに身代金を要求するマルウェア。"}, {"id": "0608", "f": "T", "sub": "セキュリティ", "term": "ボット", "desc": "感染した端末を、外部の攻撃者が遠隔で操作できるようにするマルウェア。"}, {"id": "0609", "f": "T", "sub": "セキュリティ", "term": "キーロガー", "desc": "キーボードの入力を記録して、パスワードなどを盗むソフトウェアや装置。"}, {"id": "0610", "f": "T", "sub": "セキュリティ", "term": "バックドア", "desc": "攻撃者が後から何度でも侵入できるように、こっそり作っておく裏口。"}, {"id": "0611", "f": "T", "sub": "セキュリティ", "term": "フィッシング", "desc": "本物そっくりの偽のWebサイトやメールで利用者をだまし、IDやパスワード、カードの番号などを盗む手口。"}, {"id": "0612", "f": "T", "sub": "セキュリティ", "term": "標的型攻撃", "desc": "特定の組織や人を狙い、業務に関係するように見せかけたメールなどで、マルウェアに感染させる攻撃。"}, {"id": "0613", "f": "T", "sub": "セキュリティ", "term": "ソーシャルエンジニアリング", "desc": "技術を使わずに、人の心理のすきや油断を突いて、パスワードなどの情報を盗む手口。のぞき見や、なりすましの電話など。"}, {"id": "0614", "f": "T", "sub": "セキュリティ", "term": "ショルダーハッキング", "desc": "パスワードを入力するところを、肩越しなどにのぞき見て盗む手口。"}, {"id": "0615", "f": "T", "sub": "セキュリティ", "term": "なりすまし", "desc": "他人のふりをして、システムを使ったり情報を盗んだりすること。"}, {"id": "0616", "f": "T", "sub": "セキュリティ", "term": "ブルートフォース攻撃", "desc": "考えられるすべての文字の組合せを順番に試して、パスワードを見つけ出す攻撃。総当たり攻撃とも呼ぶ。"}, {"id": "0617", "f": "T", "sub": "セキュリティ", "term": "辞書攻撃", "desc": "辞書にある単語や、よく使われる文字列を、パスワードとして順番に試す攻撃。"}, {"id": "0618", "f": "T", "sub": "セキュリティ", "term": "パスワードリスト攻撃", "desc": "他のサービスから漏れたIDとパスワードの組を使って、ログインを試す攻撃。パスワードの使い回しが狙われる。"}, {"id": "0619", "f": "T", "sub": "セキュリティ", "term": "DoS攻撃", "desc": "サーバに大量のデータを送りつけるなどして負荷をかけ、サービスを止めてしまう攻撃。", "abbr": "Denial of Service"}, {"id": "0620", "f": "T", "sub": "セキュリティ", "term": "DDoS攻撃", "desc": "多数の端末から一斉にDoS攻撃を行う攻撃。", "abbr": "Distributed Denial of Service"}, {"id": "0621", "f": "T", "sub": "セキュリティ", "term": "SQLインジェクション", "desc": "Webアプリケーションの入力欄に、データベースを不正に操作する命令（SQL）を入力して、データを盗んだり改ざんしたりする攻撃。"}, {"id": "0622", "f": "T", "sub": "セキュリティ", "term": "クロスサイトスクリプティング", "desc": "Webサイトの弱点を突いて悪意のあるスクリプトを埋め込み、利用者のブラウザで実行させる攻撃。XSSとも呼ぶ。"}, {"id": "0623", "f": "T", "sub": "セキュリティ", "term": "ゼロデイ攻撃", "desc": "ソフトウェアの脆弱性が見つかってから、修正プログラムが提供されるまでの間に、その脆弱性を突く攻撃。"}, {"id": "0624", "f": "T", "sub": "セキュリティ", "term": "中間者攻撃", "desc": "通信する2者の間に割り込み、気付かれないように通信を盗み見たり書き換えたりする攻撃。"}, {"id": "0625", "f": "T", "sub": "セキュリティ", "term": "ドライブバイダウンロード", "desc": "Webサイトを見ただけで、利用者が気付かないうちにマルウェアをダウンロードさせる攻撃。"}, {"id": "0626", "f": "T", "sub": "セキュリティ", "term": "水飲み場型攻撃", "desc": "狙う相手がよく見るWebサイトを改ざんしておき、そのサイトを見た相手をマルウェアに感染させる攻撃。"}, {"id": "0627", "f": "T", "sub": "セキュリティ", "term": "ビジネスメール詐欺", "desc": "取引先や経営者になりすました偽のメールで、偽の口座にお金を振り込ませる詐欺。BECとも呼ぶ。"}, {"id": "0628", "f": "T", "sub": "セキュリティ", "term": "サプライチェーン攻撃", "desc": "セキュリティ対策が手薄な取引先や関連会社などを経由して、本来の標的を攻撃すること。"}, {"id": "0629", "f": "T", "sub": "セキュリティ", "term": "クリプトジャッキング", "desc": "他人のコンピュータを勝手に使って、暗号資産を得るための計算（マイニング）をさせる攻撃。"}, {"id": "0630", "f": "T", "sub": "セキュリティ", "term": "ワンクリック詐欺", "desc": "Webサイトやメールのリンクを1回クリックしただけで「登録が完了した」と表示し、料金を請求する詐欺。"}, {"id": "0631", "f": "T", "sub": "セキュリティ", "term": "ファイアウォール", "desc": "外部のネットワークと内部のネットワークの間に置き、決められたルールに従って、通信を通したり止めたりする仕組み。"}, {"id": "0632", "f": "T", "sub": "セキュリティ", "term": "DMZ", "desc": "外部のネットワークと内部のネットワークの間に設ける、緩衝地帯のようなネットワーク。外部に公開するWebサーバなどを置く。", "abbr": "DeMilitarized Zone"}, {"id": "0633", "f": "T", "sub": "セキュリティ", "term": "WAF", "desc": "Webアプリケーションへの通信を調べ、SQLインジェクションなどの攻撃を見つけて防ぐ仕組み。", "abbr": "Web Application Firewall"}, {"id": "0634", "f": "T", "sub": "セキュリティ", "term": "IDS", "desc": "ネットワークやサーバへの不正な侵入を見つけて、管理者に知らせる仕組み。", "abbr": "Intrusion Detection System"}, {"id": "0635", "f": "T", "sub": "セキュリティ", "term": "IPS", "desc": "不正な侵入を見つけて知らせるだけでなく、その通信を自動で止める仕組み。", "abbr": "Intrusion Prevention System"}, {"id": "0636", "f": "T", "sub": "セキュリティ", "term": "ウイルス対策ソフト", "desc": "マルウェアを見つけて取り除くソフトウェア。マルウェアの特徴を記録した定義ファイルを、最新にしておく必要がある。"}, {"id": "0637", "f": "T", "sub": "セキュリティ", "term": "検疫ネットワーク", "desc": "社外から持ち込んだパソコンなどを、安全を確かめるまで、社内のネットワークにつながせない仕組み。"}, {"id": "0638", "f": "T", "sub": "セキュリティ", "term": "サンドボックス", "desc": "プログラムを外部から切り離した安全な環境で動かし、怪しい動きがないかを確かめる仕組み。"}, {"id": "0639", "f": "T", "sub": "セキュリティ", "term": "ペネトレーションテスト", "desc": "実際に攻撃する方法でシステムに侵入を試み、セキュリティの弱点がないかを確かめるテスト。"}, {"id": "0640", "f": "T", "sub": "セキュリティ", "term": "デジタルフォレンジックス", "desc": "不正アクセスなどの事件が起きたときに、コンピュータに残った記録を集めて分析し、証拠にすること。"}, {"id": "0641", "f": "T", "sub": "セキュリティ", "term": "MDM", "desc": "会社が社員に配ったスマートフォンなどの端末を、まとめて管理する仕組み。紛失したときに、遠隔でデータを消すこともできる。", "abbr": "Mobile Device Management"}, {"id": "0642", "f": "T", "sub": "セキュリティ", "term": "耐タンパ性", "desc": "機器の中の情報を、外から不正に読み取ったり改ざんしたりされにくい性質。"}, {"id": "0643", "f": "T", "sub": "セキュリティ", "term": "アクセス権", "desc": "ファイルなどの情報資産に対して、誰がどの操作（読む・書く・実行するなど）をしてよいかを決めた権限。"}, {"id": "0644", "f": "T", "sub": "セキュリティ", "term": "多要素認証", "desc": "知識（パスワード）・所持（スマートフォン）・生体（指紋）のうち、異なる2つ以上の要素を組み合わせて、本人を確かめる認証。"}, {"id": "0645", "f": "T", "sub": "セキュリティ", "term": "生体認証", "desc": "指紋・顔・静脈・虹彩など、体の特徴を使って本人を確かめる認証。"}, {"id": "0646", "f": "T", "sub": "セキュリティ", "term": "ワンタイムパスワード", "desc": "一度しか使えない、使い捨てのパスワード。盗まれても、次のログインには使えない。"}, {"id": "0647", "f": "T", "sub": "セキュリティ", "term": "シングルサインオン", "desc": "一度の認証で、複数のシステムやサービスを使えるようにする仕組み。SSOとも呼ぶ。"}, {"id": "0648", "f": "T", "sub": "セキュリティ", "term": "CAPTCHA", "desc": "ゆがんだ文字の読み取りなど、人間には簡単でもコンピュータには難しい問題を出して、操作しているのが人間かどうかを確かめる仕組み。"}, {"id": "0649", "f": "T", "sub": "セキュリティ", "term": "暗号化", "desc": "データを、決まった手順で、第三者が読めない形に変えること。元に戻すことを復号という。"}, {"id": "0650", "f": "T", "sub": "セキュリティ", "term": "共通鍵暗号方式", "desc": "暗号化と復号に同じ鍵を使う暗号方式。処理は速いが、鍵を相手に安全に渡す方法が課題になる。"}, {"id": "0651", "f": "T", "sub": "セキュリティ", "term": "公開鍵暗号方式", "desc": "暗号化と復号に異なる鍵（公開鍵と秘密鍵）を使う暗号方式。公開鍵で暗号化したデータは、対になる秘密鍵でしか復号できない。"}, {"id": "0652", "f": "T", "sub": "セキュリティ", "term": "ハッシュ関数", "desc": "データから、決まった長さの値（ハッシュ値）を作る関数。ハッシュ値から元のデータを求めるのは難しい。改ざんを見つけるのに使う。"}, {"id": "0653", "f": "T", "sub": "セキュリティ", "term": "デジタル署名", "desc": "公開鍵暗号の仕組みを使い、データを送った人が本人であることと、データが改ざんされていないことを確かめる技術。"}, {"id": "0654", "f": "T", "sub": "セキュリティ", "term": "認証局（CA）", "desc": "公開鍵が本人のものであることを証明する電子証明書（デジタル証明書）を発行する機関。"}, {"id": "0655", "f": "T", "sub": "セキュリティ", "term": "PKI", "desc": "公開鍵基盤のこと。認証局が発行する電子証明書を使って、公開鍵の持ち主を保証する仕組み。", "abbr": "Public Key Infrastructure"}, {"id": "0656", "f": "T", "sub": "セキュリティ", "term": "TLS", "desc": "インターネット上の通信を暗号化し、通信の相手を確かめるためのプロトコル。HTTPSで使われる。SSLの後継。", "abbr": "Transport Layer Security"}, {"id": "0657", "f": "T", "sub": "セキュリティ", "term": "ブロックチェーン", "desc": "取引の記録をブロックにまとめ、鎖のようにつないで、多数のコンピュータで共有する技術。改ざんが非常に難しい。"}, {"id": "0658", "f": "T", "sub": "セキュリティ", "term": "セキュリティパッチ", "desc": "ソフトウェアの脆弱性を直すための修正プログラム。"}, {"id": "0659", "f": "T", "sub": "セキュリティ", "term": "クリアデスク", "desc": "席を離れるときや帰るときに、机の上に書類や記録媒体を置いたままにしないこと。"}, {"id": "0660", "f": "T", "sub": "セキュリティ", "term": "クリアスクリーン", "desc": "席を離れるときに画面をロックするなどして、他の人に画面をのぞかれたり操作されたりしないようにすること。"}, {"id": "0661", "f": "T", "sub": "セキュリティ", "term": "入退室管理", "desc": "ICカードや生体認証などで、建物や部屋に入る人を管理すること。"}, {"id": "0662", "f": "T", "sub": "セキュリティ", "term": "共連れ", "desc": "認証を受けた人の後について、認証を受けずに部屋などに入ること。"}, {"id": "0663", "f": "T", "sub": "セキュリティ", "term": "ゼロトラスト", "desc": "社内のネットワークも安全とは考えずに、すべての通信やアクセスを毎回確かめるという、セキュリティの考え方。"}, {"id": "0664", "f": "T", "sub": "セキュリティ", "term": "セキュリティバイデザイン", "desc": "システムの企画や設計の段階から、セキュリティ対策を組み込んでおく考え方。"}, {"id": "0665", "f": "T", "sub": "セキュリティ", "term": "プライバシーバイデザイン", "desc": "システムの企画や設計の段階から、個人情報やプライバシーの保護を組み込んでおく考え方。"}];
window.IP_TEST = {"S": 7, "M": 4, "T": 9};
